# Let me try to use a simple cargo project with no dependencies and see if I can do regex-based HTML processing
# Actually, Python is the best option here since it has built-in HTTP support
# 
# Let me design the Python implementation:
# 1. Parse HTML with html.parser
# 2. Process elements recursively
# 3. Serialize back to HTML
# 4. Handle all the monolith-specific behavior

# The key insight is that html.parser doesn't do full HTML5 parsing
# Let me test it with some edge cases

python3 << 'EOF'
from html.parser import HTMLParser

class TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.root = {'tag': 'ROOT', 'attrs': {}, 'children': [], 'text': '', 'tail': ''}
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = {'tag': tag.lower(), 'attrs': dict(attrs), 'children': [], 'text': '', 'tail': ''}
        self.stack[-1]['children'].append(node)
        self.stack.append(node)

    def handle_endtag(self, tag):
        if len(self.stack) > 1:
            self.stack.pop()

    def handle_data(self, data):
        if self.stack[-1]['children']:
            self.stack[-1]['children'][-1]['tail'] = data
        else:
            self.stack[-1]['text'] = data

    def handle_comment(self, data):
        node = {'tag': '!--', 'data': data, 'children': [], 'text': '', 'tail': ''}
        self.stack[-1]['children'].append(node)

builder = TreeBuilder()
builder.feed('<!DOCTYPE html><html><head><title>Test</title></head><body><p>Hello &amp; World</p></body></html>')

def print_tree(node, indent=0):
    if node['tag'] == 'ROOT':
        for child in node['children']:
            print_tree(child, indent)
    else:
        print(' ' * indent + f"<{node['tag']}>")
        if node['text']:
            print(' ' * (indent+2) + f"text: {repr(node['text'])}")
        for child in node['children']:
            print_tree(child, indent+2)
        print(' ' * indent + f"</{node['tag']}>")

print_tree(builder.root)
EOF

