#!/usr/bin/env python3
"""
Monolith - Bundle web pages into a single HTML file
Reimplementation based on behavioral observation
"""

import sys
import os
import re
import base64
import urllib.request
import urllib.parse
import urllib.error
import argparse
import datetime
import ssl
import http.cookiejar
from html.parser import HTMLParser
import io

VERSION = "2.11.0"

# MIME type mapping based on file extension (from behavioral testing)
EXTENSION_MIME_TYPES = {
    'png': 'image/png',
    'jpg': 'image/jpeg',
    'jpeg': 'image/jpeg',
    'gif': 'image/gif',
    'svg': 'image/svg+xml',
    'webp': 'image/webp',
    'bmp': 'image/bmp',
    'ico': 'image/x-icon',
    'tiff': 'image/tiff',
    'tif': 'image/tiff',
    'mp3': 'audio/mpeg',
    'ogg': 'audio/ogg',
    'oga': 'audio/ogg',
    'wav': 'audio/wav',
    'mp4': 'video/mp4',
    'woff': 'font/woff',
    'woff2': 'font/woff2',
    'css': 'text/css',
    'html': 'text/html',
    'htm': 'text/html',
}

VOID_ELEMENTS = frozenset([
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
])

def get_mime_type_for_url(url):
    """Get MIME type from URL extension."""
    # Remove fragment and query
    clean_url = url.split('?')[0].split('#')[0]
    if '.' in clean_url.rsplit('/', 1)[-1]:
        ext = clean_url.rsplit('.', 1)[-1].lower()
        return EXTENSION_MIME_TYPES.get(ext, '')
    return ''


def resolve_url(base_url, url):
    """Resolve a URL relative to a base URL."""
    if not url:
        return url
    # Don't resolve data: URLs
    if url.startswith('data:'):
        return url
    # Don't resolve javascript: URLs
    if url.startswith('javascript:'):
        return url
    # Don't resolve mailto: URLs
    if url.startswith('mailto:'):
        return url
    # Don't resolve tel: URLs
    if url.startswith('tel:'):
        return url

    return urllib.parse.urljoin(base_url, url)


class Fetcher:
    """Handles fetching URLs and files."""

    def __init__(self, opts):
        self.opts = opts
        self._cache = {}

        # Set up SSL context
        if opts.insecure:
            self.ssl_ctx = ssl.create_default_context()
            self.ssl_ctx.check_hostname = False
            self.ssl_ctx.verify_mode = ssl.CERT_NONE
        else:
            self.ssl_ctx = None

        # Set up cookie jar
        self.cookie_jar = None
        if opts.cookie_file:
            self.cookie_jar = http.cookiejar.MozillaCookieJar(opts.cookie_file)
            try:
                self.cookie_jar.load()
            except Exception:
                pass

    def is_allowed_domain(self, url):
        """Check if URL is allowed based on domain filter."""
        if not self.opts.domain:
            return True

        parsed = urllib.parse.urlparse(url)
        host = parsed.netloc.lower()
        if ':' in host:
            host = host.split(':')[0]

        if self.opts.blacklist_domains:
            # Blacklist: block if matches any domain
            for domain in self.opts.domain:
                domain = domain.lower().lstrip('.')
                if host == domain or host.endswith('.' + domain):
                    return False
            return True
        else:
            # Whitelist: allow only matching domains
            for domain in self.opts.domain:
                domain = domain.lower().lstrip('.')
                if host == domain or host.endswith('.' + domain):
                    return True
            return False

    def fetch(self, url, base_url=None):
        """
        Fetch content from URL.
        Returns (content_bytes, mime_type) or None on error.
        """
        if url in self._cache:
            return self._cache[url]

        result = self._fetch_internal(url, base_url)
        self._cache[url] = result
        return result

    def _fetch_internal(self, url, base_url=None):
        parsed = urllib.parse.urlparse(url)

        if parsed.scheme == 'file':
            return self._fetch_file(url, parsed)
        elif parsed.scheme in ('http', 'https'):
            return self._fetch_http(url)
        elif parsed.scheme == 'data':
            return self._parse_data_url(url)
        else:
            return None

    def _fetch_file(self, url, parsed):
        """Fetch a local file."""
        # Convert file URL to path
        path = urllib.request.url2pathname(parsed.path)

        if not self.opts.quiet:
            print(url, file=sys.stderr)

        if not os.path.isfile(path):
            if not self.opts.quiet:
                print(f"{url} (file not found)", file=sys.stderr)
            return None

        # Overwrite the print above
        if not self.opts.quiet:
            # Re-print without error
            pass

        try:
            with open(path, 'rb') as f:
                content = f.read()

            mime_type = get_mime_type_for_url(url)
            return (content, mime_type)
        except (IOError, OSError):
            return None

    def _fetch_http(self, url):
        """Fetch an HTTP/HTTPS URL."""
        # Check domain filter
        if self.opts.domain and not self.is_allowed_domain(url):
            return None

        if not self.opts.quiet:
            print(url, file=sys.stderr)

        try:
            req = urllib.request.Request(url)
            if self.opts.user_agent:
                req.add_header('User-Agent', self.opts.user_agent)

            timeout = self.opts.timeout

            if self.ssl_ctx:
                response = urllib.request.urlopen(req, timeout=timeout, context=self.ssl_ctx)
            else:
                response = urllib.request.urlopen(req, timeout=timeout)

            content = response.read()
            content_type = response.headers.get('Content-Type', '')
            mime_type = content_type.split(';')[0].strip() if content_type else ''

            if not mime_type:
                mime_type = get_mime_type_for_url(url)

            return (content, mime_type)
        except Exception as e:
            if not self.opts.ignore_errors:
                if not self.opts.quiet:
                    print(f"{url} (error sending request for url ({url}))", file=sys.stderr)
            return None

    def _parse_data_url(self, url):
        """Parse a data: URL."""
        try:
            # data:[mediatype][;base64],data
            rest = url[5:]  # Remove 'data:'
            header, _, data = rest.partition(',')

            if ';base64' in header:
                mime_type = header.replace(';base64', '').strip()
                content = base64.b64decode(data)
            else:
                mime_type = header.strip()
                content = urllib.parse.unquote_to_bytes(data)

            return (content, mime_type)
        except Exception:
            return None


def make_data_url(content, mime_type, original_url=''):
    """Create a data: URL from content bytes and MIME type."""
    # Get fragment from original URL
    fragment = ''
    if original_url and '#' in original_url:
        fragment = '#' + original_url.split('#', 1)[1]

    encoded = base64.b64encode(content).decode('ascii')
    if mime_type:
        return f"data:{mime_type};base64,{encoded}{fragment}"
    else:
        return f"data:;base64,{encoded}{fragment}"


class CSSProcessor:
    """Process CSS content to embed URLs."""

    def __init__(self, base_url, fetcher, opts):
        self.base_url = base_url
        self.fetcher = fetcher
        self.opts = opts

    def process(self, css_text):
        """Process CSS text, embedding all URL references."""
        result = []
        i = 0

        while i < len(css_text):
            # Check for comment
            if css_text[i:i+2] == '/*':
                end = css_text.find('*/', i+2)
                if end == -1:
                    result.append(css_text[i:])
                    break
                result.append(css_text[i:end+2])
                i = end + 2
                continue

            # Check for @import
            if css_text[i:i+7].lower() == '@import':
                imp_start = i
                i += 7
                # Skip whitespace
                while i < len(css_text) and css_text[i] in ' \t\n\r':
                    i += 1

                if i < len(css_text):
                    if css_text[i:i+4].lower() == 'url(':
                        # @import url(...)
                        url, end_i = self._extract_url_func(css_text, i)
                        if url is not None:
                            embedded = self._embed_url(url)
                            result.append(f'@import url("{embedded}")')
                            i = end_i
                            continue
                    elif css_text[i] in ('"', "'"):
                        # @import "..." or @import '...'
                        quote = css_text[i]
                        end_q = css_text.find(quote, i+1)
                        if end_q != -1:
                            url = css_text[i+1:end_q]
                            embedded = self._embed_url(url)
                            result.append(f'@import "{embedded}"')
                            i = end_q + 1
                            continue

                # Couldn't parse @import, just emit as-is
                result.append('@import')
                continue

            # Check for url(...)
            if css_text[i:i+4].lower() == 'url(':
                url, end_i = self._extract_url_func(css_text, i)
                if url is not None:
                    # Check if it's a font URL
                    if self.opts.no_fonts and self._is_font_url(css_text, i):
                        result.append('url()')
                    else:
                        embedded = self._embed_url(url)
                        result.append(f'url("{embedded}")')
                    i = end_i
                    continue

            # Regular character
            result.append(css_text[i])
            i += 1

        return ''.join(result)

    def _is_font_url(self, css_text, pos):
        """Check if a url() is preceded by font-related CSS."""
        # Look backwards for @font-face or font-related property
        before = css_text[max(0, pos-100):pos].lower()
        return '@font-face' in before or 'src:' in before

    def _extract_url_func(self, css_text, start):
        """
        Extract URL from url(...) function.
        Returns (url_string, end_position) or (None, None).
        """
        # Skip 'url('
        i = start + 4

        # Skip whitespace
        while i < len(css_text) and css_text[i] in ' \t\n\r':
            i += 1

        if i >= len(css_text):
            return None, None

        if css_text[i] in ('"', "'"):
            quote = css_text[i]
            i += 1
            end = css_text.find(quote, i)
            if end == -1:
                return None, None
            url = css_text[i:end]
            i = end + 1
        else:
            # Unquoted URL
            end = i
            while end < len(css_text) and css_text[end] not in (' ', '\t', '\n', '\r', ')'):
                end += 1
            url = css_text[i:end]
            i = end

        # Skip whitespace
        while i < len(css_text) and css_text[i] in ' \t\n\r':
            i += 1

        # Skip closing )
        if i < len(css_text) and css_text[i] == ')':
            i += 1

        return url, i

    def _embed_url(self, url):
        """Embed a URL as a data URL."""
        if not url or url.startswith('data:') or url.startswith('#'):
            return url

        abs_url = resolve_url(self.base_url, url)

        result = self.fetcher.fetch(abs_url, self.base_url)
        if result is None:
            return ''

        content, mime_type = result

        if not mime_type:
            mime_type = get_mime_type_for_url(abs_url)

        return make_data_url(content, mime_type)


# HTML attribute event types
class HTMLNode:
    """Simple HTML node for our tree."""

    def __init__(self):
        self.type = 'element'  # 'element', 'text', 'comment', 'doctype', 'document'
        self.tag = ''
        self.attrs = []  # list of (name, value) tuples
        self.children = []
        self.text_data = ''  # for text/comment nodes
        self.self_closing = False  # was it <br/> etc
        self.is_inserted = False  # was this node inserted by monolith?


class HTMLParser2(HTMLParser):
    """Build an HTML tree."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.document = HTMLNode()
        self.document.type = 'document'
        self.stack = [self.document]
        self._in_raw = None  # tag name if we're in a raw text element
        self._raw_buf = []

    def current(self):
        return self.stack[-1]

    def handle_decl(self, decl):
        node = HTMLNode()
        node.type = 'doctype'
        node.text_data = decl
        self.current().children.append(node)

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        node = HTMLNode()
        node.type = 'element'
        node.tag = tag
        node.attrs = [(name.lower(), value if value is not None else '') for name, value in attrs]

        self.current().children.append(node)

        if tag in VOID_ELEMENTS:
            node.self_closing = True
        else:
            self.stack.append(node)
            if tag in ('script', 'style'):
                self._in_raw = tag
                self._raw_buf = []

    def handle_startendtag(self, tag, attrs):
        """Handle self-closing tags like <br/>"""
        tag = tag.lower()
        node = HTMLNode()
        node.type = 'element'
        node.tag = tag
        node.attrs = [(name.lower(), value if value is not None else '') for name, value in attrs]
        node.self_closing = True
        self.current().children.append(node)

    def handle_endtag(self, tag):
        tag = tag.lower()

        if self._in_raw == tag:
            # Add raw content as text child
            raw_content = ''.join(self._raw_buf)
            if raw_content:
                child = HTMLNode()
                child.type = 'text'
                child.text_data = raw_content
                self.current().children.append(child)
            self._in_raw = None
            self._raw_buf = []

        # Pop stack to find matching tag
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].type == 'element' and self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        if self._in_raw is not None:
            self._raw_buf.append(data)
            return

        node = HTMLNode()
        node.type = 'text'
        node.text_data = data
        self.current().children.append(node)

    def handle_entityref(self, name):
        """Handle &entity; references."""
        if self._in_raw is not None:
            self._raw_buf.append(f'&{name};')
            return
        node = HTMLNode()
        node.type = 'text'
        node.text_data = f'&{name};'  # Keep as-is, will be re-escaped
        self.current().children.append(node)

    def handle_charref(self, name):
        """Handle &#num; references."""
        if self._in_raw is not None:
            if name.startswith('x') or name.startswith('X'):
                char = chr(int(name[1:], 16))
            else:
                char = chr(int(name))
            self._raw_buf.append(char)
            return

        if name.startswith('x') or name.startswith('X'):
            char = chr(int(name[1:], 16))
        else:
            char = chr(int(name))

        node = HTMLNode()
        node.type = 'text'
        node.text_data = char
        self.current().children.append(node)

    def handle_comment(self, data):
        if self._in_raw is not None:
            self._raw_buf.append(f'<!--{data}-->')
            return
        node = HTMLNode()
        node.type = 'comment'
        node.text_data = data
        self.current().children.append(node)


def parse_html(html_str):
    """Parse HTML and return document node."""
    parser = HTMLParser2()
    parser.feed(html_str)
    return parser.document


def escape_text_content(text):
    """Escape text content for HTML output (already-escaped entities pass through)."""
    # Check if this is an HTML entity already (starts with & and ends with ;)
    result = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == '&':
            # Check if it's a valid entity reference
            semicolon = text.find(';', i+1)
            if semicolon != -1 and semicolon - i <= 12:
                entity = text[i+1:semicolon]
                if entity.startswith('#') or entity.isalpha() or entity.isalnum():
                    # Preserve entity as-is
                    result.append(text[i:semicolon+1])
                    i = semicolon + 1
                    continue
            result.append('&amp;')
        elif c == '<':
            result.append('&lt;')
        elif c == '>':
            result.append('&gt;')
        else:
            result.append(c)
        i += 1
    return ''.join(result)


def escape_attr_value(value):
    """Escape attribute value for double-quoted attributes."""
    value = value.replace('&', '&amp;')
    value = value.replace('"', '&quot;')
    return value


def serialize_tree(node, buf=None):
    """Serialize HTML node to string."""
    if buf is None:
        buf = io.StringIO()

    if node.type == 'document':
        for child in node.children:
            serialize_tree(child, buf)

    elif node.type == 'doctype':
        buf.write('<!DOCTYPE html>')

    elif node.type == 'text':
        # Raw text (already contains HTML entities correctly)
        # We need to determine if this is in a raw element
        buf.write(node.text_data)

    elif node.type == 'comment':
        buf.write(f'<!--{node.text_data}-->')

    elif node.type == 'element':
        tag = node.tag
        buf.write(f'<{tag}')
        for name, value in node.attrs:
            buf.write(f' {name}="{escape_attr_value(value)}"')
        buf.write('>')

        for child in node.children:
            serialize_tree(child, buf)

        if tag not in VOID_ELEMENTS or node.is_inserted:
            buf.write(f'</{tag}>')

    return buf


def find_nodes(root, predicate, stop_predicate=None):
    """Find all nodes matching predicate."""
    results = []

    def walk(node):
        if predicate(node):
            results.append(node)
        if stop_predicate and stop_predicate(node):
            return
        for child in getattr(node, 'children', []):
            walk(child)

    walk(root)
    return results


def find_head(document):
    """Find or create head element."""
    # Look for <html> then <head>
    for child in document.children:
        if child.type == 'element' and child.tag == 'html':
            for c in child.children:
                if c.type == 'element' and c.tag == 'head':
                    return c
            # Create head
            head = HTMLNode()
            head.type = 'element'
            head.tag = 'head'
            head.children = []
            head.attrs = []
            child.children.insert(0, head)
            return head

    # Look directly for head
    for child in document.children:
        if child.type == 'element' and child.tag == 'head':
            return child

    # No head found - create document structure
    # Find or create html element
    html_node = None
    for child in document.children:
        if child.type == 'element' and child.tag == 'html':
            html_node = child
            break

    if html_node is None:
        html_node = HTMLNode()
        html_node.type = 'element'
        html_node.tag = 'html'
        html_node.attrs = []
        html_node.children = []
        document.children.append(html_node)

    head = HTMLNode()
