def process_srcset(srcset, base_url, fetcher, opts):
    """Process srcset attribute, embedding image URLs."""
    if not srcset:
        return srcset

    parts = []
    for item in srcset.split(','):
        item = item.strip()
        if not item:
            continue

        tokens = item.split()
        if not tokens:
            continue

        url = tokens[0]
        descriptor = ' '.join(tokens[1:])

        if url.startswith('data:'):
            if descriptor:
                parts.append(f'{url} {descriptor}')
            else:
                parts.append(url)
            continue

        abs_url = resolve_url(base_url, url)
        result = fetcher.fetch(abs_url)

        if result is None:
            if descriptor:
                parts.append(f' {descriptor}' if descriptor else '')
            else:
                parts.append('')
        else:
            content, mime_type = result
            if not mime_type:
                mime_type = get_mime_type_for_url(abs_url)
            data_url = make_data_url(content, mime_type)
            if descriptor:
                parts.append(f'{data_url} {descriptor}')
            else:
                parts.append(data_url)

    return ', '.join(parts)


def process_document(document, base_url, opts, fetcher):
    """Process the HTML document, embedding resources."""

    # Find base URL from <base href> in document
    doc_base_url = base_url
    base_node = None

    # Walk to find base tag
    def find_base(node):
        nonlocal doc_base_url, base_node
        if node.type == 'element' and node.tag == 'base':
            href = get_attr(node, 'href')
            if href and base_node is None:
                base_node = node
                if not opts.base_url:  # Don't override if -b was specified
                    doc_base_url = href
        for child in getattr(node, 'children', []):
            find_base(child)

    find_base(document)

    # If base_url was specified via -b, update the base tag
    if opts.base_url:
        doc_base_url = opts.base_url
        if base_node is not None:
            set_attr(base_node, 'href', opts.base_url)
        else:
            # Insert base tag into head
            head = find_head(document)
            base_node = HTMLNode()
            base_node.type = 'element'
            base_node.tag = 'base'
            base_node.attrs = [('href', opts.base_url)]
            base_node.children = []
            base_node.is_inserted = True
            head.children.insert(0, base_node)

    # Process all nodes
    process_node(document, doc_base_url, opts, fetcher)

    return doc_base_url


def process_inline_style(style_value, base_url, fetcher, opts):
    """Process a style attribute value."""
    css_proc = CSSProcessor(base_url, fetcher, opts)
    return css_proc.process(style_value)


def process_node(node, base_url, opts, fetcher):
    """Process a single node and its children."""
    if node.type not in ('element', 'document'):
        return

    if node.type == 'document':
        for child in list(node.children):
            process_node(child, base_url, opts, fetcher)
        return

    tag = node.tag

    # Process inline style attribute
    style_val = get_attr(node, 'style')
    if style_val:
        processed = process_inline_style(style_val, base_url, fetcher, opts)
        set_attr(node, 'style', processed)

    # Process based on tag
    if tag == 'link':
        process_link(node, base_url, opts, fetcher)
    elif tag == 'style':
        process_style_element(node, base_url, opts, fetcher)
    elif tag == 'script':
        process_script(node, base_url, opts, fetcher)
    elif tag == 'img':
        process_img(node, base_url, opts, fetcher)
    elif tag == 'picture':
        pass  # children will be processed
    elif tag == 'source':
        process_source(node, base_url, opts, fetcher)
    elif tag in ('video', 'audio'):
        process_media(node, base_url, opts, fetcher)
    elif tag == 'iframe':
        process_iframe(node, base_url, opts, fetcher)
    elif tag == 'frame':
        process_frame(node, base_url, opts, fetcher)
    elif tag == 'input':
        process_input(node, base_url, opts, fetcher)
    elif tag == 'a':
        process_anchor(node, base_url, opts, fetcher)
    elif tag == 'form':
        process_form(node, base_url, opts, fetcher)
    elif tag in ('image',):
        # SVG image element
        process_svg_image(node, base_url, opts, fetcher)
    elif tag == 'use':
        process_svg_use(node, base_url, opts, fetcher)
    elif tag == 'noscript':
        process_noscript(node, base_url, opts, fetcher)
    elif tag == 'meta':
        process_meta(node, base_url, opts, fetcher)

    # Process children
    for child in list(node.children):
        process_node(child, base_url, opts, fetcher)


def process_link(node, base_url, opts, fetcher):
