                css_proc = CSSProcessor(abs_url, fetcher, opts)
                processed_css = css_proc.process(css_text)
                processed_bytes = processed_css.encode('utf-8')
                data_url = make_data_url(processed_bytes, 'text/css')
                set_attr(node, 'href', data_url)
            else:
                del_attr(node, 'href')
        elif href and href.startswith('data:'):
            # Re-encode data: CSS URL
            result = fetcher._parse_data_url(href)
            if result:
                content, mime_type = result
                css_text = content.decode('utf-8', errors='replace')
                css_proc = CSSProcessor(base_url, fetcher, opts)
