                processed_bytes = processed_css.encode('utf-8')
                data_url = make_data_url(processed_bytes, 'text/css')
                set_attr(node, 'href', data_url)

    elif rel in ('icon', 'shortcut icon', 'apple-touch-icon', 'apple-touch-icon-precomposed'):
        if href and not href.startswith('data:'):
            abs_url = resolve_url(base_url, href)
            result = fetcher.fetch(abs_url)
            if result is not None:
                content, mime_type = result
                if not mime_type:
                    mime_type = get_mime_type_for_url(abs_url)
                data_url = make_data_url(content, mime_type)
                set_attr(node, 'href', data_url)
            else:
                del_attr(node, 'href')

    elif rel == 'preload':
        # Remove rel attribute for preload
        del_attr(node, 'rel')
        # Don't embed the resource

