        # Resolve URL but don't embed
        if href:
            abs_url = resolve_url(base_url, href)
            set_attr(node, 'href', abs_url)

    elif rel in ('canonical', 'alternate', 'manifest', 'next', 'prev'):
        # Resolve URL but don't embed
        if href and not href.startswith('data:'):
            abs_url = resolve_url(base_url, href)
            set_attr(node, 'href', abs_url)

    # For other link types, leave as-is


def process_style_element(node, base_url, opts, fetcher):
