def handle_noscript_unwrap(document):
    """Replace <noscript> elements with comment-wrapped content."""
    def process_noscript_node(parent, parent_idx, node):
        if node.type == 'element' and node.tag == 'noscript':
            # Replace this node in parent's children
            idx = parent_idx
            new_children = list(parent.children[:idx])

            # Add <!--noscript-->
            comment_start = HTMLNode()
            comment_start.type = 'comment'
            comment_start.text_data = 'noscript'
            new_children.append(comment_start)

            # Add noscript's children
            new_children.extend(node.children)

            # Add <!--/noscript-->
            comment_end = HTMLNode()
            comment_end.type = 'comment'
            comment_end.text_data = '/noscript'
            new_children.append(comment_end)

            new_children.extend(parent.children[idx+1:])
            parent.children = new_children
            return True
        return False

    def walk(node):
        i = 0
        while i < len(getattr(node, 'children', [])):
            child = node.children[i]
            if process_noscript_node(node, i, child):
                # Don't increment i since we replaced in place
                i += 1  # Actually skip ahead past the replaced content
            else:
                walk(child)
                i += 1

    walk(document)


