    """Build CSP string based on options."""
    parts = []

    if opts.isolate:
        parts.append("default-src 'unsafe-eval' 'unsafe-inline' data:")

    if opts.no_css:
        parts.append("style-src 'none'")

    if opts.no_fonts:
