def serialize_html_node(node, buf, in_raw_element=False):
    """Serialize a node to HTML."""
    if node.type == 'document':
        for child in node.children:
            serialize_html_node(child, buf, False)
        return

    if node.type == 'doctype':
        buf.write('<!DOCTYPE html>')
        return

    if node.type == 'text':
        text = node.text_data
        if in_raw_element:
            # Raw text - don't escape
            buf.write(text)
        else:
            # Escape HTML entities
            buf.write(_escape_html_text(text))
        return

    if node.type == 'comment':
        buf.write(f'<!--{node.text_data}-->')
        return

    if node.type == 'element':
        tag = node.tag
        buf.write(f'<{tag}')
        for attr_name, attr_val in node.attrs:
            buf.write(f' {attr_name}="{_escape_attr(attr_val)}"')
        buf.write('>')

        is_raw = tag in ('script', 'style')
        for child in node.children:
            serialize_html_node(child, buf, is_raw)

        # End tag
        if tag in VOID_ELEMENTS and not node.is_inserted:
            pass  # No closing tag for void elements from parsed HTML
        else:
            buf.write(f'</{tag}>')


def _escape_html_text(text):
    """Escape text for HTML text nodes, preserving existing &xxx; entities."""
    result = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == '&':
            # Check if followed by a valid entity
            j = i + 1
            # Named entity or numeric ref
            if j < len(text) and text[j] == '#':
                # Numeric character reference
                k = j + 1
                if k < len(text) and text[k] in ('x', 'X'):
                    k += 1
                    while k < len(text) and text[k] in '0123456789abcdefABCDEF':
                        k += 1
                else:
                    while k < len(text) and text[k].isdigit():
                        k += 1
                if k < len(text) and text[k] == ';':
                    result.append(text[i:k+1])
                    i = k + 1
                    continue
            else:
                # Named entity
                k = j
                while k < len(text) and (text[k].isalpha() or text[k].isdigit()):
                    k += 1
                if k < len(text) and text[k] == ';' and k > j:
                    result.append(text[i:k+1])
                    i = k + 1
                    continue
            result.append('&amp;')
        elif c == '<':
            result.append('&lt;')
        elif c == '>':
            result.append('&gt;')
        else:
            result.append(c)
        i += 1
    return ''.join(result)


def _escape_attr(value):
    """Escape attribute value for double-quoted attributes."""
    value = value.replace('&', '&amp;')
    value = value.replace('"', '&quot;')
    return value


