    http_equiv = get_attr(node, 'http-equiv', '').lower()
    if http_equiv == 'refresh':
        del_attr(node, 'http-equiv')


def _get_text_content(node):
    """Get text content of element."""
    parts = []
    for child in node.children:
        if child.kind == 'text':
            parts.append(child.data)
    return ''.join(parts)


def _proc_srcset(srcset, base_url, fetcher):
    """Process srcset attribute."""
    parts = []
    for item in srcset.split(','):
        item = item.strip()
        if not item:
            continue
        tokens = item.split(None, 1)
        if not tokens:
            continue
        url = tokens[0]
        desc = tokens[1] if len(tokens) > 1 else ''

        if url.startswith('data:'):
            parts.append(f'{url} {desc}'.strip())
            continue

        data_url, ok = _embed_resource(url, base_url, fetcher)
        if ok and data_url:
            parts.append(f'{data_url} {desc}'.strip())
        else:
            parts.append(f' {desc}'.strip() if desc else '')

    return ', '.join(parts)


