def set_encoding(head, encoding):
    """Add or update charset meta."""
    for child in head.children:
        if child.kind == 'element' and child.tag == 'meta':
            if has_attr(child, 'charset'):
                set_attr(child, 'charset', encoding)
                return
            http_eq = get_attr(child, 'http-equiv', '').lower()
            if http_eq == 'content-type':
                content = get_attr(child, 'content', '')
                if 'charset=' in content.lower():
                    content = re.sub(r'charset=[^;,\s]+', f'charset={encoding}', content, flags=re.I)
                else:
                    content = f'{content};charset={encoding}'
                set_attr(child, 'content', content)
                return

    # Add charset meta at end of head
    meta = ElementNode('meta', [['charset', encoding]])
    meta.inserted = True
    head.children.append(meta)


