    __slots__ = ['kind', 'children']
    def __init__(self):
        super().__init__('document')
        self.children = []

class DoctypeNode(Node):
    __slots__ = ['kind']
    def __init__(self):
        super().__init__('doctype')

class TextNode(Node):
    __slots__ = ['kind', 'data']
    def __init__(self, data):
        super().__init__('text')
        self.data = data

class CommentNode(Node):
    __slots__ = ['kind', 'data']
    def __init__(self, data):
        super().__init__('comment')
        self.data = data

