            self._raw_buf.append(char)
        else:
            self.current.children.append(TextNode(char))

    def handle_comment(self, data):
        if self._raw_tag:
            self._raw_buf.append(f'<!--{data}-->')
        else:
            self.current.children.append(CommentNode(data))


def parse_html(html_str):
    """Parse HTML string into a DOM tree."""
    builder = TreeBuilder()
    builder.feed(html_str)
    return builder.document


# ===== DOM helpers =====

def get_attr(node, name, default=None):
    for pair in node.attrs:
        if pair[0] == name:
            return pair[1]
    return default

def set_attr(node, name, value):
    for pair in node.attrs:
        if pair[0] == name:
            pair[1] = value
            return
    node.attrs.append([name, value])

def del_attr(node, name):
    node.attrs = [p for p in node.attrs if p[0] != name]

def has_attr(node, name):
    return any(p[0] == name for p in node.attrs)

def find_element(root, tag, max_depth=None):
    """Find first element with given tag."""
    result = [None]
    def walk(node, depth):
        if result[0] is not None:
            return
        if max_depth is not None and depth > max_depth:
            return
        if node.kind == 'element' and node.tag == tag:
            result[0] = node
            return
        for child in getattr(node, 'children', []):
            walk(child, depth + 1)
    walk(root, 0)
    return result[0]

def find_all_elements(root, tag):
    """Find all elements with given tag."""
    results = []
    def walk(node):
        if node.kind == 'element' and node.tag == tag:
            results.append(node)
        for child in getattr(node, 'children', []):
            walk(child)
    walk(root)
    return results

def walk_elements(root, callback, parent=None, idx=0):
    """Walk all nodes, callback(node, parent, idx)."""
    callback(root, parent, idx)
    for i, child in enumerate(getattr(root, 'children', [])):
        walk_elements(child, callback, root, i)


def find_or_create_head(document):
    """Find or create head element in document."""
    html = find_element(document, 'html', max_depth=1)
    if html:
        head = find_element(html, 'head', max_depth=1)
        if head:
            return head
        # Create head
        head = ElementNode('head', [])
        html.children.insert(0, head)
        return head

    # Look directly under document
    for child in document.children:
        if child.kind == 'element' and child.tag == 'head':
            return child

    # Need to create html structure
    html_node = None
    for child in document.children:
        if child.kind == 'element' and child.tag == 'html':
            html_node = child
            break

    if html_node is None:
        html_node = ElementNode('html', [])
        document.children.append(html_node)

    head = ElementNode('head', [])
    html_node.children.insert(0, head)
    return head


# ===== HTML Serializer =====

def escape_text(text):
    """Escape text content. Preserves existing &xxx; entities."""
    result = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == '&':
            # Check if this is an existing entity reference
            j = i + 1
            if j < n and text[j] == '#':
                # Numeric reference
                k = j + 1
                if k < n and text[k] in ('x', 'X'):
                    k += 1
                    while k < n and text[k] in '0123456789abcdefABCDEF':
                        k += 1
                else:
                    while k < n and text[k].isdigit():
                        k += 1
                if k < n and text[k] == ';':
                    result.append(text[i:k+1])
                    i = k + 1
                    continue
            else:
                # Named entity
                k = j
                while k < n and (text[k].isalpha() or text[k].isdigit()):
                    k += 1
                if k < n and text[k] == ';' and k > j:
                    result.append(text[i:k+1])
                    i = k + 1
                    continue
            result.append('&amp;')
        elif c == '<':
            result.append('&lt;')
        elif c == '>':
            result.append('&gt;')
        else:
            result.append(c)
        i += 1
    return ''.join(result)


def escape_attr(value):
    """Escape attribute value for double-quoted attributes."""
    return value.replace('&', '&amp;').replace('"', '&quot;')


def serialize(node, buf, in_raw=False):
    """Serialize a node to HTML."""
    k = node.kind

    if k == 'document':
        for child in node.children:
            serialize(child, buf, False)

    elif k == 'doctype':
        buf.write('<!DOCTYPE html>')

    elif k == 'text':
        if in_raw:
            buf.write(node.data)
        else:
            buf.write(escape_text(node.data))

    elif k == 'comment':
        buf.write(f'<!--{node.data}-->')

    elif k == 'element':
        tag = node.tag
        buf.write(f'<{tag}')
        for name, val in node.attrs:
            buf.write(f' {name}="{escape_attr(val)}"')
        buf.write('>')

        is_raw = tag in RAW_TEXT_ELEMENTS
        for child in node.children:
            serialize(child, buf, is_raw)

        # Close tag: void elements from parsed HTML don't get one
        # BUT void elements inserted by monolith get a closing tag
        if tag not in VOID_ELEMENTS or node.inserted:
            buf.write(f'</{tag}>')


def serialize_document(doc):
    """Serialize document to HTML string."""
    buf = io.StringIO()
    serialize(doc, buf)
    return buf.getvalue()


# ===== CSS Processor =====

class CSSProcessor:
    """Process CSS content to embed URL references."""

    def __init__(self, base_url, fetcher, opts):
        self.base_url = base_url
        self.fetcher = fetcher
        self.opts = opts

    def process(self, css):
        """Process CSS string, embedding all URL references."""
        out = []
        i = 0
        n = len(css)

        while i < n:
            # Check for comment /* ... */
            if css[i:i+2] == '/*':
                end = css.find('*/', i+2)
                if end == -1:
                    out.append(css[i:])
                    break
                out.append(css[i:end+2])
                i = end + 2
                continue

            # Check for @font-face handling
            # Check for @import
            if i + 7 <= n and css[i:i+7].lower() == '@import':
                result = self._process_import(css, i)
                if result is not None:
                    text, new_i = result
                    out.append(text)
                    i = new_i
                    continue

            # Check for url(...)
            if i + 4 <= n and css[i:i+4].lower() == 'url(':
                url, end_i = self._extract_url(css, i + 4)
                if url is not None:
                    embedded = self._embed(url, is_font=self._is_font_context(css, i))
                    out.append(f'url("{embedded}")')
                    i = end_i
                    continue

            out.append(css[i])
            i += 1

        return ''.join(out)

    def _is_font_context(self, css, pos):
        """Check if position is inside a @font-face rule."""
        # Look back for @font-face
        before = css[max(0, pos-500):pos].lower()
        # Find last @font-face
        last_ff = before.rfind('@font-face')
        if last_ff == -1:
            return False
        # Check if we're still inside that rule (count braces)
        segment = before[last_ff:]
        open_braces = segment.count('{')
        close_braces = segment.count('}')
        return open_braces > close_braces

    def _process_import(self, css, start):
        """Process @import directive."""
        i = start + 7  # Skip '@import'
        n = len(css)

        # Skip whitespace
        while i < n and css[i] in ' \t\n\r':
            i += 1

        if i >= n:
            return None

        if css[i:i+4].lower() == 'url(':
            url, end_i = self._extract_url(css, i + 4)
            if url is not None:
                embedded = self._embed(url)
                return f'@import url("{embedded}")', end_i
        elif css[i] in ('"', "'"):
            quote = css[i]
            end_q = css.find(quote, i + 1)
            if end_q != -1:
                url = css[i+1:end_q]
                embedded = self._embed(url)
                return f'@import "{embedded}"', end_q + 1

        return None

    def _extract_url(self, css, start):
        """Extract URL from inside url( ...). start is position after '('."""
        i = start
        n = len(css)

        # Skip whitespace
        while i < n and css[i] in ' \t\n\r':
            i += 1

        if i >= n:
            return None, None

        if css[i] in ('"', "'"):
            quote = css[i]
            i += 1
            end = css.find(quote, i)
            if end == -1:
                return None, None
            url = css[i:end]
            i = end + 1
        else:
            # Unquoted
            end = i
            while end < n and css[end] not in (' ', '\t', '\n', '\r', ')'):
                end += 1
            url = css[i:end]
            i = end

        # Skip whitespace and closing )
        while i < n and css[i] in ' \t\n\r':
            i += 1
        if i < n and css[i] == ')':
            i += 1

        return url, i

    def _embed(self, url, is_font=False):
        """Embed a URL as data URL."""
        if not url or url.startswith('data:') or url.startswith('#'):
            return url

        if is_font and self.opts.no_fonts:
            return ''

        abs_url = resolve_url(self.base_url, url)
        result = self.fetcher.fetch(abs_url)
        if result is None:
            return ''

        content, mime_type = result
        if not mime_type:
            mime_type = get_mime_type(abs_url)

        encoded = base64.b64encode(content).decode('ascii')
        if mime_type:
            return f'data:{mime_type};base64,{encoded}'
        else:
            return f'data:;base64,{encoded}'


# ===== Fetcher =====

class Fetcher:
    """Fetch URLs with caching."""

    def __init__(self, opts):
        self.opts = opts
        self._cache = {}

        if opts.insecure:
            self._ssl = ssl.create_default_context()
            self._ssl.check_hostname = False
            self._ssl.verify_mode = ssl.CERT_NONE
        else:
            self._ssl = None

    def fetch(self, url):
        """Fetch URL. Returns (bytes, mime_type) or None."""
        if url in self._cache:
            return self._cache[url]
        r = self._fetch(url)
        self._cache[url] = r
        return r

    def _fetch(self, url):
        parsed = urllib.parse.urlparse(url)

        if parsed.scheme == 'file':
            return self._fetch_file(url, parsed)
        elif parsed.scheme in ('http', 'https'):
            return self._fetch_http(url)
        elif parsed.scheme == 'data':
            return self._parse_data(url)
        return None

    def _fetch_file(self, url, parsed):
        path = urllib.request.url2pathname(parsed.path)
        if not os.path.isfile(path):
            if not self.opts.quiet:
                print(f'{url} (file not found)', file=sys.stderr)
            return None
        if not self.opts.quiet:
            print(url, file=sys.stderr)
        try:
            with open(path, 'rb') as f:
                data = f.read()
            return (data, get_mime_type(url))
        except OSError:
            return None

    def _fetch_http(self, url):
        if not self._domain_allowed(url):
            return None
        if not self.opts.quiet:
            print(url, file=sys.stderr)
        try:
            req = urllib.request.Request(url)
            if self.opts.user_agent:
                req.add_header('User-Agent', self.opts.user_agent)
            kw = {'timeout': self.opts.timeout}
            if self._ssl:
                kw['context'] = self._ssl
            resp = urllib.request.urlopen(req, **kw)
            data = resp.read()
            ct = resp.headers.get('Content-Type', '')
            mime = ct.split(';')[0].strip() if ct else ''
            if not mime:
                mime = get_mime_type(url)
            return (data, mime)
        except Exception as e:
            if not self.opts.quiet:
                print(f'{url} (error sending request for url ({url}))', file=sys.stderr)
            return None

    def _parse_data(self, url):
        """Parse data: URL."""
        try:
            rest = url[5:]
            header, _, data = rest.partition(',')
            if ';base64' in header:
                mime = header.replace(';base64', '').strip()
                content = base64.b64decode(data)
            else:
                mime = header.strip()
                content = urllib.parse.unquote_to_bytes(data)
            return (content, mime)
        except Exception:
            return None

    def _domain_allowed(self, url):
        if not self.opts.domain:
            return True
        parsed = urllib.parse.urlparse(url)
        host = parsed.netloc.lower().split(':')[0]

        if self.opts.blacklist_domains:
            for d in self.opts.domain:
                d = d.lower().lstrip('.')
                if host == d or host.endswith('.' + d):
                    return False
            return True
        else:
            for d in self.opts.domain:
                d = d.lower().lstrip('.')
                if host == d or host.endswith('.' + d):
                    return True
            return False


# ===== Document Processor =====

def process_document(document, base_url, opts, fetcher):
    """Process document, embedding all resources. Returns effective base URL."""

    # Find base tag
    effective_base = base_url
    base_node = None

    def find_base(node):
        nonlocal effective_base, base_node
        if node.kind == 'element' and node.tag == 'base':
            href = get_attr(node, 'href')
            if href and base_node is None:
                base_node = node
                if not opts.base_url:
                    effective_base = href
        for c in getattr(node, 'children', []):
            find_base(c)
    find_base(document)

    # Handle -b option
    if opts.base_url:
        effective_base = opts.base_url
        head = find_or_create_head(document)
        if base_node is not None:
            set_attr(base_node, 'href', opts.base_url)
        else:
            bn = ElementNode('base', [['href', opts.base_url]])
            bn.inserted = True
            head.children.insert(0, bn)

    # Process all elements with context
    _process_node(document, effective_base, opts, fetcher, parent_tag=None)

    return effective_base


def _process_node(node, base_url, opts, fetcher, parent_tag=None):
    """Process a node recursively."""
    if node.kind not in ('element', 'document'):
        return

    if node.kind == 'document':
        for child in node.children:
            _process_node(child, base_url, opts, fetcher, None)
        return

    tag = node.tag

    # Process inline style attribute on any element
    style = get_attr(node, 'style')
    if style:
        css_proc = CSSProcessor(base_url, fetcher, opts)
        set_attr(node, 'style', css_proc.process(style))

    # Tag-specific processing
    if tag == 'link':
        _proc_link(node, base_url, opts, fetcher)
    elif tag == 'style':
        _proc_style(node, base_url, opts, fetcher)
    elif tag == 'script':
        _proc_script(node, base_url, opts, fetcher)
    elif tag == 'img':
        _proc_img(node, base_url, opts, fetcher)
    elif tag == 'source':
        _proc_source(node, base_url, opts, fetcher, parent_tag)
    elif tag in ('video', 'audio'):
        _proc_media(node, base_url, opts, fetcher)
    elif tag == 'iframe':
        _proc_iframe(node, base_url, opts, fetcher)
    elif tag == 'frame':
        _proc_frame(node, base_url, opts, fetcher)
    elif tag == 'input':
        _proc_input(node, base_url, opts, fetcher)
    elif tag == 'a':
        _proc_anchor(node, base_url, opts)
    elif tag == 'form':
        _proc_form(node, base_url, opts)
    elif tag == 'image':
        # SVG image
        _proc_svg_image(node, base_url, opts, fetcher)
    elif tag == 'use':
        _proc_svg_use(node, base_url, opts, fetcher)
    elif tag == 'noscript':
        pass  # handled separately
    elif tag == 'meta':
        _proc_meta(node)

    # Process children (with current tag as parent context)
    for child in node.children:
        _process_node(child, base_url, opts, fetcher, tag)


def _embed_resource(url, base_url, fetcher, mime_override=None):
    """Fetch and return (data_url, success)."""
    if not url or url.startswith('data:'):
        return url, True

    abs_url = resolve_url(base_url, url)
    result = fetcher.fetch(abs_url)
    if result is None:
        return None, False

    content, mime_type = result
    if mime_override:
        mime_type = mime_override
    elif not mime_type:
        mime_type = get_mime_type(abs_url)

    # Preserve fragment
    fragment = ''
    if '#' in url:
        fragment = '#' + url.split('#', 1)[1]

    encoded = base64.b64encode(content).decode('ascii')
    if mime_type:
        return f'data:{mime_type};base64,{encoded}{fragment}', True
    else:
        return f'data:;base64,{encoded}{fragment}', True


def _proc_link(node, base_url, opts, fetcher):
    rel = get_attr(node, 'rel', '').lower().strip()
    href = get_attr(node, 'href', '')

    # Remove integrity attribute
    del_attr(node, 'integrity')

    if rel == 'stylesheet':
        if opts.no_css:
            del_attr(node, 'href')
            return
        if href:
            if href.startswith('data:'):
                # Re-process data: CSS
                r = fetcher._parse_data(href)
                if r:
                    css = r[0].decode('utf-8', errors='replace')
                    proc = CSSProcessor(base_url, fetcher, opts).process(css)
                    enc = base64.b64encode(proc.encode('utf-8')).decode('ascii')
                    set_attr(node, 'href', f'data:text/css;base64,{enc}')
            else:
                abs_url = resolve_url(base_url, href)
                result = fetcher.fetch(abs_url)
                if result:
                    css = result[0].decode('utf-8', errors='replace')
                    proc = CSSProcessor(abs_url, fetcher, opts).process(css)
                    enc = base64.b64encode(proc.encode('utf-8')).decode('ascii')
                    set_attr(node, 'href', f'data:text/css;base64,{enc}')
                else:
                    del_attr(node, 'href')

    elif rel in ('icon', 'shortcut icon', 'apple-touch-icon', 'apple-touch-icon-precomposed'):
        if href and not href.startswith('data:'):
            data_url, ok = _embed_resource(href, base_url, fetcher)
            if ok and data_url:
                set_attr(node, 'href', data_url)
            else:
                del_attr(node, 'href')

    elif rel == 'preload':
        del_attr(node, 'rel')
        # Don't embed

    elif rel in ('prefetch', 'canonical', 'alternate', 'manifest', 'next', 'prev',
                 'dns-prefetch', 'preconnect'):
        if href and not href.startswith('data:') and not href.startswith('#'):
            abs_url = resolve_url(base_url, href)
            set_attr(node, 'href', abs_url)
    # Other rel types: leave as-is


def _proc_style(node, base_url, opts, fetcher):
    if opts.no_css:
        node.children = []
        return

    css_text = _get_text_content(node)
    if css_text:
        proc = CSSProcessor(base_url, fetcher, opts).process(css_text)
        node.children = [TextNode(proc)]


def _proc_script(node, base_url, opts, fetcher):
    del_attr(node, 'integrity')

    if opts.no_js:
        node.children = []
        del_attr(node, 'src')
        return

    src = get_attr(node, 'src', '')
    if src:
        if src.startswith('data:'):
            r = fetcher._parse_data(src)
            if r:
                js = r[0].decode('utf-8', errors='replace')
                node.children = [TextNode(js)]
                del_attr(node, 'src')
        else:
            abs_url = resolve_url(base_url, src)
            r = fetcher.fetch(abs_url)
            if r:
                js = r[0].decode('utf-8', errors='replace')
                node.children = [TextNode(js)]
                del_attr(node, 'src')
            else:
                del_attr(node, 'src')


BLANK_PNG_URL = (
    'data:image/png,%89PNG%0D%0A%1A%0A%00%00%00%0DIHDR%00%00%00%0D%00%00%00%0D'
    '%08%04%00%00%00%D8%E2%2C%F7%00%00%00%11IDATx%DAcd%C0%09%18G%A5%28%96%02%00'
    '%0A%F8%00%0E%CB%8A%EB%16%00%00%00%00IEND%AEB%60%82'
)


def _proc_img(node, base_url, opts, fetcher):
    src = get_attr(node, 'src', '')
    srcset = get_attr(node, 'srcset', '')

    if opts.no_images:
        set_attr(node, 'src', BLANK_PNG_URL)
        if srcset:
            del_attr(node, 'srcset')
        return

    if src and not src.startswith('data:'):
        data_url, ok = _embed_resource(src, base_url, fetcher)
        if ok and data_url:
            set_attr(node, 'src', data_url)
        else:
            del_attr(node, 'src')

    if srcset:
        set_attr(node, 'srcset', _proc_srcset(srcset, base_url, fetcher))


def _proc_source(node, base_url, opts, fetcher, parent_tag):
    src = get_attr(node, 'src', '')
    srcset = get_attr(node, 'srcset', '')

    # Check parent context for filtering
    no_src = False
    if parent_tag == 'video' and opts.no_video:
        no_src = True
    elif parent_tag == 'audio' and opts.no_audio:
        no_src = True

    if no_src:
        if src:
            del_attr(node, 'src')
        if srcset:
            del_attr(node, 'srcset')
        return

    if src and not src.startswith('data:'):
        data_url, ok = _embed_resource(src, base_url, fetcher)
        if ok and data_url:
            set_attr(node, 'src', data_url)
        else:
            del_attr(node, 'src')

    if srcset:
        set_attr(node, 'srcset', _proc_srcset(srcset, base_url, fetcher))


def _proc_media(node, base_url, opts, fetcher):
    tag = node.tag
    src = get_attr(node, 'src', '')

    is_video = tag == 'video'
    is_audio = tag == 'audio'

    if (is_video and opts.no_video) or (is_audio and opts.no_audio):
        if src:
            del_attr(node, 'src')
        return

    if src and not src.startswith('data:'):
        data_url, ok = _embed_resource(src, base_url, fetcher)
        if ok and data_url:
            set_attr(node, 'src', data_url)
        else:
            del_attr(node, 'src')


def _proc_iframe(node, base_url, opts, fetcher):
    src = get_attr(node, 'src', '')

    if opts.no_frames:
        set_attr(node, 'src', '')
        return

    if src and not src.startswith('data:'):
        abs_url = resolve_url(base_url, src)
        # Get fragment
        fragment = ''
        if '#' in src:
            fragment = '#' + src.split('#', 1)[1]

        r = fetcher.fetch(abs_url)
        if r:
            content, mime = r
            # Process HTML content
            sub_html = content.decode('utf-8', errors='replace')
            sub_doc = parse_html(sub_html)
            # Process the subdocument (without inserting robots meta etc.)
            _process_node(sub_doc, abs_url, opts, fetcher, None)
            sub_out = serialize_document(sub_doc)
            enc = base64.b64encode(sub_out.encode('utf-8')).decode('ascii')
            data_url = f'data:text/html;base64,{enc}'
            if fragment:
                data_url += fragment
            set_attr(node, 'src', data_url)
        else:
            del_attr(node, 'src')


def _proc_frame(node, base_url, opts, fetcher):
    _proc_iframe(node, base_url, opts, fetcher)


def _proc_input(node, base_url, opts, fetcher):
    t = get_attr(node, 'type', '').lower()
    if t != 'image':
        return

    src = get_attr(node, 'src', '')
    if opts.no_images:
        set_attr(node, 'src', BLANK_PNG_URL)
        return

    if src and not src.startswith('data:'):
        data_url, ok = _embed_resource(src, base_url, fetcher)
        if ok and data_url:
            set_attr(node, 'src', data_url)
        else:
            del_attr(node, 'src')


def _proc_anchor(node, base_url, opts):
    href = get_attr(node, 'href', '')
    if href:
        low = href.lower()
        if (not low.startswith('#') and not low.startswith('javascript:') and
                not low.startswith('mailto:') and not low.startswith('tel:') and
                not low.startswith('data:')):
            set_attr(node, 'href', resolve_url(base_url, href))

    if opts.no_js:
        # Remove event handlers
        node.attrs = [[k, v] for k, v in node.attrs if not k.startswith('on')]
        href = get_attr(node, 'href', '')
        if href and href.lower().startswith('javascript:'):
            set_attr(node, 'href', 'javascript:;')


def _proc_form(node, base_url, opts):
    action = get_attr(node, 'action', '')
    if action:
        low = action.lower()
        if not low.startswith('javascript:') and not low.startswith('data:'):
            set_attr(node, 'action', resolve_url(base_url, action))


def _proc_svg_image(node, base_url, opts, fetcher):
    if opts.no_images:
        del_attr(node, 'href')
        del_attr(node, 'xlink:href')
        return

    for attr in ('href', 'xlink:href'):
        val = get_attr(node, attr, '')
        if val and not val.startswith('data:'):
            data_url, ok = _embed_resource(val, base_url, fetcher)
            if ok and data_url:
                set_attr(node, attr, data_url)
            else:
                del_attr(node, attr)


def _proc_svg_use(node, base_url, opts, fetcher):
    for attr in ('href', 'xlink:href'):
        val = get_attr(node, attr, '')
        if val and not val.startswith('#') and not val.startswith('data:'):
            data_url, ok = _embed_resource(val, base_url, fetcher)
            if ok and data_url:
                set_attr(node, attr, data_url)
            else:
                del_attr(node, attr)


def _proc_meta(node):
    """Process meta elements."""
    http_equiv = get_attr(node, 'http-equiv', '').lower()
    if http_equiv == 'refresh':
        del_attr(node, 'http-equiv')


def _get_text_content(node):
    """Get text content of element."""
    parts = []
    for child in node.children:
        if child.kind == 'text':
            parts.append(child.data)
    return ''.join(parts)


def _proc_srcset(srcset, base_url, fetcher):
    """Process srcset attribute."""
    parts = []
    for item in srcset.split(','):
        item = item.strip()
        if not item:
            continue
        tokens = item.split(None, 1)
        if not tokens:
            continue
        url = tokens[0]
        desc = tokens[1] if len(tokens) > 1 else ''

        if url.startswith('data:'):
            parts.append(f'{url} {desc}'.strip())
            continue

        data_url, ok = _embed_resource(url, base_url, fetcher)
        if ok and data_url:
            parts.append(f'{data_url} {desc}'.strip())
        else:
            parts.append(f' {desc}'.strip() if desc else '')

    return ', '.join(parts)


# ===== JS removal =====

def apply_no_js(node):
    """Remove all JS from document."""
    if node.kind == 'element':
        # Remove event handler attributes
        node.attrs = [[k, v] for k, v in node.attrs if not k.lower().startswith('on')]
        # Replace javascript: hrefs
        for pair in node.attrs:
            if pair[0] in ('href', 'action') and pair[1].lower().startswith('javascript:'):
                pair[1] = 'javascript:;'
    for c in getattr(node, 'children', []):
        apply_no_js(c)


# ===== Noscript unwrap =====

def unwrap_noscript(node):
    """Replace noscript elements with comment-wrapped content."""
    if not hasattr(node, 'children'):
        return

    new_children = []
    for child in node.children:
        if child.kind == 'element' and child.tag == 'noscript':
            new_children.append(CommentNode('noscript'))
            new_children.extend(child.children)
            new_children.append(CommentNode('/noscript'))
        else:
            unwrap_noscript(child)
            new_children.append(child)
    node.children = new_children


