def set_robots_meta(head):
    """Add or update robots meta tag in head."""
    for child in head.children:
        if child.kind == 'element' and child.tag == 'meta':
            name = get_attr(child, 'name', '').lower()
            if name == 'robots':
                set_attr(child, 'content', 'none')
                return

    # Add new robots meta at end of head
    meta = ElementNode('meta', [['name', 'robots'], ['content', 'none']])
    meta.inserted = True
    head.children.append(meta)


# ===== CSP =====

def build_csp(opts):
    """Build CSP string."""
    parts = []
    if opts.isolate:
        parts.append("default-src 'unsafe-eval' 'unsafe-inline' data:")
    if opts.no_css:
        parts.append("style-src 'none'")
    if opts.no_fonts:
        parts.append("font-src 'none'")
    if opts.no_frames:
        parts.append("frame-src 'none'")
        parts.append("child-src 'none'")
    if opts.no_js:
        parts.append("script-src 'none'")
    if opts.no_images:
        parts.append("img-src data:")

    if not parts:
        return None
    return '; '.join(parts) + ';'


def add_csp(head, csp):
    """Add CSP meta at beginning of head."""
    meta = ElementNode('meta', [['http-equiv', 'Content-Security-Policy'], ['content', csp]])
    meta.inserted = True
    head.children.insert(0, meta)


# ===== Encoding =====

def set_encoding(head, encoding):
    """Add or update charset meta."""
    for child in head.children:
        if child.kind == 'element' and child.tag == 'meta':
            if has_attr(child, 'charset'):
                set_attr(child, 'charset', encoding)
                return
            http_eq = get_attr(child, 'http-equiv', '').lower()
            if http_eq == 'content-type':
                content = get_attr(child, 'content', '')
                if 'charset=' in content.lower():
                    content = re.sub(r'charset=[^;,\s]+', f'charset={encoding}', content, flags=re.I)
                else:
                    content = f'{content};charset={encoding}'
                set_attr(child, 'content', content)
                return

    # Add charset meta at end of head
    meta = ElementNode('meta', [['charset', encoding]])
    meta.inserted = True
    head.children.append(meta)


