# ===== HTML Node types =====

class Node:
    __slots__ = ['kind']
    def __init__(self, kind):
        self.kind = kind

class DocumentNode(Node):
    __slots__ = ['kind', 'children']
    def __init__(self):
        super().__init__('document')
        self.children = []

class DoctypeNode(Node):
    __slots__ = ['kind']
    def __init__(self):
        super().__init__('doctype')

class TextNode(Node):
    __slots__ = ['kind', 'data']
    def __init__(self, data):
        super().__init__('text')
        self.data = data

class CommentNode(Node):
    __slots__ = ['kind', 'data']
    def __init__(self, data):
        super().__init__('comment')
        self.data = data

class ElementNode(Node):
    __slots__ = ['kind', 'tag', 'attrs', 'children', 'void', 'inserted']
    def __init__(self, tag, attrs):
        super().__init__('element')
        self.tag = tag
        self.attrs = attrs  # list of [name, value]
        self.children = []
        self.void = tag in VOID_ELEMENTS
        self.inserted = False  # True if inserted by monolith (gets closing tag)


# ===== HTML Parser =====

class TreeBuilder(HTMLParser):
    """Build a DOM tree from HTML."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.document = DocumentNode()
        self.stack = [self.document]
        self._raw_tag = None
        self._raw_buf = []

    @property
    def current(self):
        return self.stack[-1]

    def handle_decl(self, decl):
        self.current.children.append(DoctypeNode())

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        node_attrs = [[n.lower(), (v if v is not None else '')] for n, v in attrs]
        node = ElementNode(tag, node_attrs)
        self.current.children.append(node)
        if tag not in VOID_ELEMENTS:
            self.stack.append(node)
            if tag in RAW_TEXT_ELEMENTS:
                self._raw_tag = tag
                self._raw_buf = []

    def handle_startendtag(self, tag, attrs):
        """Handle self-closing tags like <br/>"""
        self.handle_starttag(tag, attrs)
        tag = tag.lower()
        if tag not in VOID_ELEMENTS and self.stack[-1].tag == tag:
            self.stack.pop()

    def handle_endtag(self, tag):
        tag = tag.lower()

        if self._raw_tag == tag:
            # Flush raw content
            raw = ''.join(self._raw_buf)
            if raw:
                self.current.children.append(TextNode(raw))
            self._raw_buf = []
            self._raw_tag = None

        # Find matching element in stack
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].kind == 'element' and self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        if self._raw_tag:
            self._raw_buf.append(data)
        else:
            self.current.children.append(TextNode(data))

    def handle_entityref(self, name):
        """Handle &entity; references - keep as HTML entity string."""
        text = f'&{name};'
        if self._raw_tag:
            self._raw_buf.append(text)
        else:
            self.current.children.append(TextNode(text))

    def handle_charref(self, name):
        """Handle &#N; or &#xN; references - decode to character."""
        try:
            if name.startswith(('x', 'X')):
                char = chr(int(name[1:], 16))
            else:
                char = chr(int(name))
        except (ValueError, OverflowError):
            char = ''
        if self._raw_tag:
            self._raw_buf.append(char)
        else:
            self.current.children.append(TextNode(char))

    def handle_comment(self, data):
        if self._raw_tag:
            self._raw_buf.append(f'<!--{data}-->')
        else:
            self.current.children.append(CommentNode(data))


def parse_html(html_str):
    """Parse HTML string into a DOM tree."""
    builder = TreeBuilder()
    builder.feed(html_str)
