import urllib.parse
import urllib.error
import datetime
import ssl
import io
from html.parser import HTMLParser

VERSION = "2.11.0"

# MIME type mapping (from behavioral testing)
EXTENSION_MIME_TYPES = {
    'png': 'image/png',
    'jpg': 'image/jpeg',
    'jpeg': 'image/jpeg',
    'gif': 'image/gif',
    'svg': 'image/svg+xml',
    'webp': 'image/webp',
    'bmp': 'image/bmp',
