}

VOID_ELEMENTS = frozenset([
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
])

RAW_TEXT_ELEMENTS = frozenset(['script', 'style'])


def get_mime_type(url):
    path = url.split('?')[0].split('#')[0]
    if '.' in path.rsplit('/', 1)[-1]:
        ext = path.rsplit('.', 1)[-1].lower()
        return EXTENSION_MIME_TYPES.get(ext, '')
    return ''


def resolve_url(base, url):
    if not url:
        return url
    low = url.lower()
    if (low.startswith('data:') or low.startswith('javascript:') or
            low.startswith('mailto:') or low.startswith('tel:')):
        return url
    return urllib.parse.urljoin(base, url)


# ===== DOM Nodes =====

class DocumentNode:
    __slots__ = ['kind', 'children']
    def __init__(self):
        self.kind = 'document'
        self.children = []

class DoctypeNode:
    __slots__ = ['kind']
    def __init__(self):
        self.kind = 'doctype'

class TextNode:
    __slots__ = ['kind', 'data']
    def __init__(self, data):
        self.kind = 'text'
        self.data = data

class CommentNode:
    __slots__ = ['kind', 'data']
    def __init__(self, data):
        self.kind = 'comment'
        self.data = data

class ElementNode:
    __slots__ = ['kind', 'tag', 'attrs', 'children', 'inserted']
    def __init__(self, tag, attrs=None):
        self.kind = 'element'
        self.tag = tag
        self.attrs = attrs if attrs is not None else []  # list of [name, value]
        self.children = []
        self.inserted = False  # inserted by monolith (gets closing tag even if void)


# ===== HTML Parser =====

class TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.document = DocumentNode()
        self.stack = [self.document]
        self._raw_tag = None
        self._raw_buf = []

    @property
    def current(self):
        return self.stack[-1]

    def handle_decl(self, decl):
        self.current.children.append(DoctypeNode())

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        node_attrs = [[n.lower(), (v if v is not None else '')] for n, v in attrs]
        node = ElementNode(tag, node_attrs)
        self.current.children.append(node)
        if tag not in VOID_ELEMENTS:
            self.stack.append(node)
            if tag in RAW_TEXT_ELEMENTS:
                self._raw_tag = tag
                self._raw_buf = []

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        node_attrs = [[n.lower(), (v if v is not None else '')] for n, v in attrs]
        node = ElementNode(tag, node_attrs)
        self.current.children.append(node)
        # Don't push onto stack

    def handle_endtag(self, tag):
        tag = tag.lower()
        if self._raw_tag == tag:
            raw = ''.join(self._raw_buf)
            if raw:
                self.current.children.append(TextNode(raw))
            self._raw_buf = []
            self._raw_tag = None
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].kind == 'element' and self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        if self._raw_tag:
            self._raw_buf.append(data)
        else:
            self.current.children.append(TextNode(data))

    def handle_entityref(self, name):
        text = f'&{name};'
        if self._raw_tag:
            self._raw_buf.append(text)
        else:
            self.current.children.append(TextNode(text))

    def handle_charref(self, name):
        try:
            if name.startswith(('x', 'X')):
                char = chr(int(name[1:], 16))
            else:
                char = chr(int(name))
        except (ValueError, OverflowError):
            char = ''
        if self._raw_tag:
            self._raw_buf.append(char)
        else:
            self.current.children.append(TextNode(char))

    def handle_comment(self, data):
        if self._raw_tag:
            self._raw_buf.append(f'<!--{data}-->')
        else:
            self.current.children.append(CommentNode(data))


def parse_html(html_str):
    b = TreeBuilder()
    b.feed(html_str)
    return b.document


# ===== DOM helpers =====

def get_attr(node, name, default=None):
    for p in node.attrs:
        if p[0] == name:
            return p[1]
    return default

def set_attr(node, name, value):
    for p in node.attrs:
        if p[0] == name:
            p[1] = value
            return
    node.attrs.append([name, value])

def del_attr(node, name):
    node.attrs = [p for p in node.attrs if p[0] != name]

def has_attr(node, name):
    return any(p[0] == name for p in node.attrs)

def find_element(root, tag, depth=0, max_depth=None):
    if max_depth is not None and depth > max_depth:
        return None
    if root.kind == 'element' and root.tag == tag:
        return root
    for c in getattr(root, 'children', []):
        r = find_element(c, tag, depth+1, max_depth)
        if r:
            return r
    return None

def find_or_create_head(document):
    html = None
    for c in document.children:
        if c.kind == 'element' and c.tag == 'html':
            html = c
            break

    if html:
        for c in html.children:
            if c.kind == 'element' and c.tag == 'head':
                return c
        head = ElementNode('head')
        html.children.insert(0, head)
        return head

    for c in document.children:
        if c.kind == 'element' and c.tag == 'head':
            return c

    html = ElementNode('html')
    document.children.append(html)
    head = ElementNode('head')
    html.children.insert(0, head)
    return head


# ===== Serializer =====

def _escape_text(text):
    result = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == '&':
            j = i + 1
            if j < n and text[j] == '#':
                k = j + 1
                if k < n and text[k] in ('x', 'X'):
                    k += 1
                    while k < n and text[k] in '0123456789abcdefABCDEF':
                        k += 1
                else:
                    while k < n and text[k].isdigit():
                        k += 1
                if k < n and text[k] == ';':
                    result.append(text[i:k+1])
                    i = k + 1
                    continue
            else:
                k = j
                while k < n and (text[k].isalpha() or text[k].isdigit()):
                    k += 1
                if k < n and text[k] == ';' and k > j:
                    result.append(text[i:k+1])
                    i = k + 1
                    continue
            result.append('&amp;')
        elif c == '<':
            result.append('&lt;')
        elif c == '>':
            result.append('&gt;')
        else:
            result.append(c)
        i += 1
    return ''.join(result)


def _escape_attr(v):
    return v.replace('&', '&amp;').replace('"', '&quot;')


def _serialize(node, buf, in_raw=False):
    k = node.kind
    if k == 'document':
        for c in node.children:
            _serialize(c, buf, False)
    elif k == 'doctype':
        buf.write('<!DOCTYPE html>')
    elif k == 'text':
        buf.write(node.data if in_raw else _escape_text(node.data))
    elif k == 'comment':
        buf.write(f'<!--{node.data}-->')
    elif k == 'element':
        tag = node.tag
        buf.write(f'<{tag}')
        for name, val in node.attrs:
            buf.write(f' {name}="{_escape_attr(val)}"')
        buf.write('>')
        is_raw = tag in RAW_TEXT_ELEMENTS
        for c in node.children:
            _serialize(c, buf, is_raw)
        if tag not in VOID_ELEMENTS or node.inserted:
            buf.write(f'</{tag}>')


def serialize_document(doc):
    buf = io.StringIO()
    _serialize(doc, buf)
    return buf.getvalue()


# ===== CSS Processor =====

class CSSProcessor:
    def __init__(self, base_url, fetcher, opts):
        self.base_url = base_url
        self.fetcher = fetcher
        self.opts = opts

    def process(self, css):
        out = []
        i = 0
        n = len(css)
        while i < n:
            # Comment
            if css[i:i+2] == '/*':
                end = css.find('*/', i+2)
                if end == -1:
                    out.append(css[i:])
                    break
                out.append(css[i:end+2])
                i = end + 2
                continue
            # @import
            if i+7 <= n and css[i:i+7].lower() == '@import':
                r = self._import(css, i)
                if r:
                    out.append(r[0])
                    i = r[1]
                    continue
            # url(...)
            if i+4 <= n and css[i:i+4].lower() == 'url(':
                url, ei = self._extract_url(css, i+4)
                if url is not None:
                    is_font = self._in_font_face(css, i)
                    emb = self._embed(url, is_font)
                    out.append(f'url("{emb}")')
                    i = ei
                    continue
            out.append(css[i])
            i += 1
        return ''.join(out)

    def _in_font_face(self, css, pos):
        before = css[max(0,pos-500):pos].lower()
        lff = before.rfind('@font-face')
        if lff == -1:
            return False
        seg = before[lff:]
        return seg.count('{') > seg.count('}')

    def _import(self, css, start):
        i = start + 7
        n = len(css)
        while i < n and css[i] in ' \t\n\r':
            i += 1
        if i >= n:
            return None
        if css[i:i+4].lower() == 'url(':
            url, ei = self._extract_url(css, i+4)
            if url is not None:
                return f'@import url("{self._embed(url)}")', ei
        elif css[i] in ('"', "'"):
            q = css[i]
            e = css.find(q, i+1)
            if e != -1:
                return f'@import "{self._embed(css[i+1:e])}"', e+1
        return None

    def _extract_url(self, css, start):
        i = start
        n = len(css)
        while i < n and css[i] in ' \t\n\r':
            i += 1
        if i >= n:
            return None, None
        if css[i] in ('"', "'"):
            q = css[i]; i += 1
            e = css.find(q, i)
            if e == -1:
                return None, None
            url = css[i:e]; i = e+1
        else:
            e = i
            while e < n and css[e] not in (' ', '\t', '\n', '\r', ')'):
                e += 1
            url = css[i:e]; i = e
        while i < n and css[i] in ' \t\n\r':
            i += 1
        if i < n and css[i] == ')':
            i += 1
        return url, i

    def _embed(self, url, is_font=False):
        if not url or url.startswith('data:') or url.startswith('#'):
            return url
        if is_font and self.opts.no_fonts:
            return ''
        abs_url = resolve_url(self.base_url, url)
        r = self.fetcher.fetch(abs_url)
        if r is None:
            return ''
        content, mime = r
        if not mime:
            mime = get_mime_type(abs_url)
        enc = base64.b64encode(content).decode('ascii')
        return f'data:{mime};base64,{enc}' if mime else f'data:;base64,{enc}'


# ===== Fetcher =====

class Fetcher:
    def __init__(self, opts):
        self.opts = opts
        self._cache = {}
        if opts.insecure:
            self._ssl = ssl.create_default_context()
            self._ssl.check_hostname = False
            self._ssl.verify_mode = ssl.CERT_NONE
        else:
            self._ssl = None

    def fetch(self, url):
        if url in self._cache:
            return self._cache[url]
        r = self._do_fetch(url)
        self._cache[url] = r
        return r

    def _do_fetch(self, url):
        p = urllib.parse.urlparse(url)
        if p.scheme == 'file':
            return self._file(url, p)
        elif p.scheme in ('http', 'https'):
            return self._http(url)
        elif p.scheme == 'data':
            return self._data(url)
        return None

    def _file(self, url, p):
        path = urllib.request.url2pathname(p.path)
        if not os.path.isfile(path):
            if not self.opts.quiet:
                print(f'{url} (file not found)', file=sys.stderr)
            return None
        if not self.opts.quiet:
            print(url, file=sys.stderr)
        try:
            with open(path, 'rb') as f:
                return (f.read(), get_mime_type(url))
        except OSError:
            return None

    def _http(self, url):
        if not self._domain_ok(url):
            return None
        if not self.opts.quiet:
            print(url, file=sys.stderr)
        try:
            req = urllib.request.Request(url)
            if self.opts.user_agent:
                req.add_header('User-Agent', self.opts.user_agent)
            kw = {'timeout': self.opts.timeout}
            if self._ssl:
                kw['context'] = self._ssl
            resp = urllib.request.urlopen(req, **kw)
            data = resp.read()
            ct = resp.headers.get('Content-Type', '')
            mime = ct.split(';')[0].strip() if ct else ''
            return (data, mime or get_mime_type(url))
        except Exception:
            if not self.opts.quiet:
                print(f'{url} (error sending request for url ({url}))', file=sys.stderr)
            return None

    def _data(self, url):
        try:
            rest = url[5:]
            hdr, _, data = rest.partition(',')
            if ';base64' in hdr:
                mime = hdr.replace(';base64', '').strip()
                return (base64.b64decode(data), mime)
            else:
                return (urllib.parse.unquote_to_bytes(data), hdr.strip())
        except Exception:
            return None

    def _domain_ok(self, url):
        if not self.opts.domain:
            return True
        host = urllib.parse.urlparse(url).netloc.lower().split(':')[0]
        if self.opts.blacklist_domains:
            for d in self.opts.domain:
                d = d.lower().lstrip('.')
                if host == d or host.endswith('.'+d):
                    return False
            return True
        else:
            for d in self.opts.domain:
                d = d.lower().lstrip('.')
                if host == d or host.endswith('.'+d):
                    return True
            return False


# ===== Document Processing =====

BLANK_PNG = ('data:image/png,%89PNG%0D%0A%1A%0A%00%00%00%0DIHDR%00%00%00%0D%00%00%00%0D'
             '%08%04%00%00%00%D8%E2%2C%F7%00%00%00%11IDATx%DAcd%C0%09%18G%A5%28%96%02%00'
             '%0A%F8%00%0E%CB%8A%EB%16%00%00%00%00IEND%AEB%60%82')


def process_document(document, base_url, opts, fetcher):
    """Process document, embedding resources. Returns effective base URL."""
    effective_base = base_url
    base_node = None

    def find_base(node):
        nonlocal effective_base, base_node
        if node.kind == 'element' and node.tag == 'base':
            href = get_attr(node, 'href')
            if href and base_node is None:
                base_node = node
                if not opts.base_url:
                    effective_base = href
        for c in getattr(node, 'children', []):
            find_base(c)
    find_base(document)

    if opts.base_url:
        effective_base = opts.base_url
        head = find_or_create_head(document)
        if base_node is not None:
            set_attr(base_node, 'href', opts.base_url)
        else:
            bn = ElementNode('base', [['href', opts.base_url]])
            bn.inserted = True
            head.children.insert(0, bn)

    _proc_node(document, effective_base, opts, fetcher, None)
    return effective_base


def _proc_node(node, base, opts, fetcher, parent_tag):
    if node.kind not in ('element', 'document'):
        return
    if node.kind == 'document':
        for c in node.children:
            _proc_node(c, base, opts, fetcher, None)
        return

    tag = node.tag

    # Inline style
    style = get_attr(node, 'style')
    if style:
        set_attr(node, 'style', CSSProcessor(base, fetcher, opts).process(style))

    # Tag processing
    if tag == 'link':
        _link(node, base, opts, fetcher)
    elif tag == 'style':
        _style(node, base, opts, fetcher)
    elif tag == 'script':
        _script(node, base, opts, fetcher)
    elif tag == 'img':
        _img(node, base, opts, fetcher)
    elif tag == 'source':
        _source(node, base, opts, fetcher, parent_tag)
    elif tag in ('video', 'audio'):
        _media(node, base, opts, fetcher)
    elif tag in ('iframe', 'frame'):
        _iframe(node, base, opts, fetcher)
    elif tag == 'input':
        _input(node, base, opts, fetcher)
    elif tag == 'a':
        _anchor(node, base, opts)
    elif tag == 'form':
        _form(node, base)
    elif tag == 'image':
        _svg_image(node, base, opts, fetcher)
    elif tag == 'use':
        _svg_use(node, base, opts, fetcher)
    elif tag == 'meta':
        _meta(node)

    for c in node.children:
        _proc_node(c, base, opts, fetcher, tag)


def _embed(url, base, fetcher, mime_override=None):
    """Embed URL as data URL. Returns (data_url, ok)."""
    if not url or url.startswith('data:'):
        return url, True
    abs_url = resolve_url(base, url)
    r = fetcher.fetch(abs_url)
    if r is None:
        return None, False
    content, mime = r
    if mime_override:
        mime = mime_override
    elif not mime:
        mime = get_mime_type(abs_url)
    frag = ('#' + url.split('#', 1)[1]) if '#' in url else ''
    enc = base64.b64encode(content).decode('ascii')
    return (f'data:{mime};base64,{enc}{frag}' if mime
            else f'data:;base64,{enc}{frag}'), True


def _link(node, base, opts, fetcher):
    rel = get_attr(node, 'rel', '').lower().strip()
    href = get_attr(node, 'href', '')
    del_attr(node, 'integrity')

    if rel == 'stylesheet':
        if opts.no_css:
            del_attr(node, 'href')
            return
        if href:
            if href.startswith('data:'):
                r = fetcher._data(href)
                if r:
                    css = r[0].decode('utf-8', errors='replace')
                    proc = CSSProcessor(base, fetcher, opts).process(css)
                    enc = base64.b64encode(proc.encode('utf-8')).decode('ascii')
                    set_attr(node, 'href', f'data:text/css;base64,{enc}')
            else:
                abs_url = resolve_url(base, href)
                r = fetcher.fetch(abs_url)
                if r:
                    css = r[0].decode('utf-8', errors='replace')
                    proc = CSSProcessor(abs_url, fetcher, opts).process(css)
                    enc = base64.b64encode(proc.encode('utf-8')).decode('ascii')
                    set_attr(node, 'href', f'data:text/css;base64,{enc}')
                else:
                    del_attr(node, 'href')

    elif rel in ('icon', 'shortcut icon', 'apple-touch-icon', 'apple-touch-icon-precomposed'):
        if href and not href.startswith('data:'):
            du, ok = _embed(href, base, fetcher)
            if ok and du:
                set_attr(node, 'href', du)
            else:
                del_attr(node, 'href')

    elif rel == 'preload':
        del_attr(node, 'rel')

    elif rel in ('prefetch', 'canonical', 'alternate', 'manifest', 'next', 'prev',
                 'dns-prefetch', 'preconnect'):
        if href and not href.startswith('data:') and not href.startswith('#'):
            set_attr(node, 'href', resolve_url(base, href))


def _style(node, base, opts, fetcher):
    if opts.no_css:
        node.children = []
        return
    css = ''.join(c.data for c in node.children if c.kind == 'text')
    if css:
        node.children = [TextNode(CSSProcessor(base, fetcher, opts).process(css))]


def _script(node, base, opts, fetcher):
    del_attr(node, 'integrity')
    if opts.no_js:
        node.children = []
        del_attr(node, 'src')
        return
    src = get_attr(node, 'src', '')
    if src:
        if src.startswith('data:'):
            r = fetcher._data(src)
            if r:
                node.children = [TextNode(r[0].decode('utf-8', errors='replace'))]
                del_attr(node, 'src')
        else:
            abs_url = resolve_url(base, src)
            r = fetcher.fetch(abs_url)
            if r:
                node.children = [TextNode(r[0].decode('utf-8', errors='replace'))]
                del_attr(node, 'src')
            else:
                del_attr(node, 'src')


def _img(node, base, opts, fetcher):
    src = get_attr(node, 'src', '')
    srcset = get_attr(node, 'srcset', '')
    if opts.no_images:
        set_attr(node, 'src', BLANK_PNG)
        if srcset:
            del_attr(node, 'srcset')
        return
    if src and not src.startswith('data:'):
        du, ok = _embed(src, base, fetcher)
        if ok and du:
            set_attr(node, 'src', du)
        else:
            del_attr(node, 'src')
    if srcset:
        set_attr(node, 'srcset', _srcset(srcset, base, fetcher))


def _source(node, base, opts, fetcher, parent_tag):
    src = get_attr(node, 'src', '')
    srcset = get_attr(node, 'srcset', '')
    no_src = ((parent_tag == 'video' and opts.no_video) or
              (parent_tag == 'audio' and opts.no_audio))
    if no_src:
        if src: del_attr(node, 'src')
        if srcset: del_attr(node, 'srcset')
        return
    if src and not src.startswith('data:'):
        du, ok = _embed(src, base, fetcher)
        if ok and du:
            set_attr(node, 'src', du)
        else:
            del_attr(node, 'src')
    if srcset:
        set_attr(node, 'srcset', _srcset(srcset, base, fetcher))


def _media(node, base, opts, fetcher):
    tag = node.tag
    src = get_attr(node, 'src', '')
    no = (tag == 'video' and opts.no_video) or (tag == 'audio' and opts.no_audio)
    if no:
        if src: del_attr(node, 'src')
        return
    if src and not src.startswith('data:'):
        du, ok = _embed(src, base, fetcher)
        if ok and du:
            set_attr(node, 'src', du)
        else:
            del_attr(node, 'src')


def _iframe(node, base, opts, fetcher):
    src = get_attr(node, 'src', '')
    if opts.no_frames:
        set_attr(node, 'src', '')
        return
    if src and not src.startswith('data:'):
        abs_url = resolve_url(base, src)
        frag = ('#' + src.split('#', 1)[1]) if '#' in src else ''
        r = fetcher.fetch(abs_url)
        if r:
            sub = parse_html(r[0].decode('utf-8', errors='replace'))
            _proc_node(sub, abs_url, opts, fetcher, None)
            out = serialize_document(sub)
            enc = base64.b64encode(out.encode('utf-8')).decode('ascii')
            set_attr(node, 'src', f'data:text/html;base64,{enc}{frag}')
        else:
            del_attr(node, 'src')


def _input(node, base, opts, fetcher):
    if get_attr(node, 'type', '').lower() != 'image':
        return
    src = get_attr(node, 'src', '')
    if opts.no_images:
        set_attr(node, 'src', BLANK_PNG)
        return
    if src and not src.startswith('data:'):
        du, ok = _embed(src, base, fetcher)
        if ok and du:
            set_attr(node, 'src', du)
        else:
            del_attr(node, 'src')


def _anchor(node, base, opts):
    href = get_attr(node, 'href', '')
    if href:
        low = href.lower()
        if not (low.startswith('#') or low.startswith('javascript:') or
                low.startswith('mailto:') or low.startswith('tel:') or
                low.startswith('data:')):
            set_attr(node, 'href', resolve_url(base, href))
    if opts.no_js:
        node.attrs = [[k, v] for k, v in node.attrs if not k.startswith('on')]
        href = get_attr(node, 'href', '')
        if href and href.lower().startswith('javascript:'):
            set_attr(node, 'href', 'javascript:;')


def _form(node, base):
    action = get_attr(node, 'action', '')
    if action and not action.lower().startswith(('javascript:', 'data:')):
        set_attr(node, 'action', resolve_url(base, action))


def _svg_image(node, base, opts, fetcher):
    if opts.no_images:
        del_attr(node, 'href')
        del_attr(node, 'xlink:href')
        return
    for attr in ('href', 'xlink:href'):
        val = get_attr(node, attr, '')
        if val and not val.startswith('data:'):
            du, ok = _embed(val, base, fetcher)
            if ok and du:
                set_attr(node, attr, du)
            else:
                del_attr(node, attr)


def _svg_use(node, base, opts, fetcher):
    for attr in ('href', 'xlink:href'):
        val = get_attr(node, attr, '')
        if val and not val.startswith('#') and not val.startswith('data:'):
            du, ok = _embed(val, base, fetcher)
            if ok and du:
                set_attr(node, attr, du)
            else:
                del_attr(node, attr)


def _meta(node):
    if get_attr(node, 'http-equiv', '').lower() == 'refresh':
        del_attr(node, 'http-equiv')


def _srcset(srcset, base, fetcher):
    parts = []
    for item in srcset.split(','):
        item = item.strip()
        if not item:
            continue
        tokens = item.split(None, 1)
        url = tokens[0]
        desc = tokens[1] if len(tokens) > 1 else ''
        if url.startswith('data:'):
            parts.append(f'{url} {desc}'.strip())
        else:
            du, ok = _embed(url, base, fetcher)
            parts.append(f'{du} {desc}'.strip() if (ok and du) else desc.strip())
    return ', '.join(parts)


# ===== Post-processing =====

def apply_no_js(node):
    if node.kind == 'element':
        node.attrs = [[k, v] for k, v in node.attrs if not k.lower().startswith('on')]
        for p in node.attrs:
            if p[0] in ('href', 'action') and p[1].lower().startswith('javascript:'):
                p[1] = 'javascript:;'
    for c in getattr(node, 'children', []):
        apply_no_js(c)


def unwrap_noscript(node):
    if not hasattr(node, 'children'):
        return
    new = []
    for c in node.children:
        if c.kind == 'element' and c.tag == 'noscript':
            new.append(CommentNode('noscript'))
            new.extend(c.children)
            new.append(CommentNode('/noscript'))
        else:
            unwrap_noscript(c)
            new.append(c)
    node.children = new


def set_robots_meta(head):
    for c in head.children:
        if c.kind == 'element' and c.tag == 'meta':
            if get_attr(c, 'name', '').lower() == 'robots':
                set_attr(c, 'content', 'none')
                return
    m = ElementNode('meta', [['name', 'robots'], ['content', 'none']])
    m.inserted = True
    head.children.append(m)


def build_csp(opts):
    parts = []
    if opts.isolate:
        parts.append("default-src 'unsafe-eval' 'unsafe-inline' data:")
    if opts.no_css:
        parts.append("style-src 'none'")
    if opts.no_fonts:
        parts.append("font-src 'none'")
    if opts.no_frames:
        parts.append("frame-src 'none'")
        parts.append("child-src 'none'")
    if opts.no_js:
        parts.append("script-src 'none'")
    if opts.no_images:
        parts.append("img-src data:")
    return ('; '.join(parts) + ';') if parts else None


def add_csp(head, csp):
    m = ElementNode('meta', [['http-equiv', 'Content-Security-Policy'], ['content', csp]])
    m.inserted = True
    head.children.insert(0, m)


def set_encoding(head, enc):
    for c in head.children:
        if c.kind == 'element' and c.tag == 'meta':
            if has_attr(c, 'charset'):
                set_attr(c, 'charset', enc)
                return
            if get_attr(c, 'http-equiv', '').lower() == 'content-type':
                content = get_attr(c, 'content', '')
                if 'charset=' in content.lower():
                    content = re.sub(r'charset=[^;,\s]+', f'charset={enc}', content, flags=re.I)
                else:
                    content += f';charset={enc}'
                set_attr(c, 'content', content)
                return
    m = ElementNode('meta', [['charset', enc]])
    m.inserted = True
    head.children.append(m)


# ===== Target fetching =====

def fetch_target(target, opts):
    if target == '-':
        return sys.stdin.buffer.read(), opts.base_url or 'http://example.com/'

    p = urllib.parse.urlparse(target)

    if p.scheme in ('http', 'https'):
        fetcher = Fetcher(opts)
        if not opts.quiet:
            print(target, file=sys.stderr)
        r = fetcher.fetch(target)
        if r is None:
            print('Error: could not retrieve target document', file=sys.stderr)
            sys.exit(1)
        return r[0], target

    elif p.scheme == 'file':
        path = urllib.request.url2pathname(p.path)
        if not opts.quiet:
            print(target, file=sys.stderr)
        if not os.path.isfile(path):
            if not opts.quiet:
                print(f'{target} (file not found)', file=sys.stderr)
            print('Error: could not retrieve target document', file=sys.stderr)
            sys.exit(1)
        with open(path, 'rb') as f:
            return f.read(), target

    else:
        # File path or bare URL
        if os.path.isabs(target) or target.startswith('./') or target.startswith('../'):
            abs_path = os.path.abspath(target)
        else:
            abs_path = os.path.abspath(target)

        if os.path.isfile(abs_path):
            base_url = 'file://' + abs_path
            if not opts.quiet:
                print(base_url, file=sys.stderr)
            with open(abs_path, 'rb') as f:
                return f.read(), base_url

        # Try as HTTP
        http_url = f'http://{target}'
        if not opts.quiet:
            print(http_url, file=sys.stderr)
        fetcher = Fetcher(opts)
        r = fetcher.fetch(http_url)
        if r is None:
            print('Error: could not retrieve target document', file=sys.stderr)
            sys.exit(1)
        return r[0], http_url


# ===== MHTML =====

def to_mhtml(html_content, base_url):
    """Convert to MHTML format with \r\n line endings for headers."""
    boundary = '----=_NextPart_000_0000'
    CRLF = '\r\n'
    # Headers use CRLF
    lines = [
        f'MIME-Version: 1.0{CRLF}',
        f'Content-Type: multipart/related; boundary="{boundary}"{CRLF}',
        CRLF,
        f'------=_NextPart_000_0000{CRLF}',
        f'Content-Type: text/html; charset="utf-8"{CRLF}',
        f'Content-Location: http://example.com/{CRLF}',
        CRLF,
        html_content,
        f'------=_NextPart_000_0000--{CRLF}',
    ]
    return ''.join(lines)


