# ===== Argument Parsing =====

import re as _re

def parse_args():
    """Parse command line arguments manually to match original behavior."""
    prog = os.path.basename(sys.argv[0])
    args = sys.argv[1:]

    class Opts:
        pass

    opts = Opts()
    opts.target = None
    opts.no_audio = False
    opts.base_url = None
    opts.blacklist_domains = False
    opts.no_css = False
    opts.cookie_file = None
    opts.domain = []
    opts.ignore_errors = False
    opts.encoding = None
    opts.no_frames = False
    opts.no_fonts = False
    opts.no_images = False
    opts.isolate = False
    opts.no_js = False
    opts.insecure = False
    opts.mhtml = False
    opts.no_metadata = False
    opts.unwrap_noscript = False
    opts.output = None
    opts.quiet = False
    opts.timeout = 60
    opts.user_agent = None
    opts.no_video = False

    i = 0
    while i < len(args):
        a = args[i]

        if a in ('-h', '--help'):
            print_help(prog)
            sys.exit(0)
        elif a in ('-V', '--version'):
            print(f'monolith {VERSION}')
            sys.exit(0)
        elif a in ('-a', '--no-audio'):
            opts.no_audio = True
        elif a in ('-b', '--base-url'):
            i += 1
            if i >= len(args):
                _arg_error(prog, f"argument {a}: expected one argument")
            opts.base_url = args[i]
        elif a.startswith('--base-url='):
            opts.base_url = a[11:]
        elif a in ('-B', '--blacklist-domains'):
            opts.blacklist_domains = True
        elif a in ('-c', '--no-css'):
            opts.no_css = True
        elif a in ('-C', '--cookie-file'):
            i += 1
            if i >= len(args):
                _arg_error(prog, f"argument {a}: expected one argument")
            opts.cookie_file = args[i]
        elif a in ('-d', '--domain'):
            i += 1
            if i >= len(args):
                _arg_error(prog, f"argument {a}: expected one argument")
            opts.domain.append(args[i])
        elif a.startswith('--domain='):
            opts.domain.append(a[9:])
        elif a in ('-e', '--ignore-errors'):
            opts.ignore_errors = True
        elif a in ('-E', '--encoding'):
            i += 1
            if i >= len(args):
                _arg_error(prog, f"argument {a}: expected one argument")
            opts.encoding = args[i]
        elif a.startswith('--encoding='):
            opts.encoding = a[11:]
        elif a in ('-f', '--no-frames'):
            opts.no_frames = True
        elif a in ('-F', '--no-fonts'):
            opts.no_fonts = True
        elif a in ('-i', '--no-images'):
            opts.no_images = True
        elif a in ('-I', '--isolate'):
            opts.isolate = True
        elif a in ('-j', '--no-js'):
            opts.no_js = True
        elif a in ('-k', '--insecure'):
            opts.insecure = True
        elif a in ('-m', '--mhtml'):
            opts.mhtml = True
        elif a in ('-M', '--no-metadata'):
            opts.no_metadata = True
        elif a in ('-n', '--unwrap-noscript'):
            opts.unwrap_noscript = True
        elif a in ('-o', '--output'):
            i += 1
            if i >= len(args):
                _arg_error(prog, f"argument {a}: expected one argument")
            opts.output = args[i]
        elif a.startswith('--output='):
            opts.output = a[9:]
        elif a in ('-q', '--quiet'):
            opts.quiet = True
        elif a in ('-t', '--timeout'):
            i += 1
            if i >= len(args):
                _arg_error(prog, f"argument {a}: expected one argument")
            try:
                opts.timeout = int(args[i])
            except ValueError:
                _arg_error(prog, f"argument {a}: invalid int value: '{args[i]}'")
        elif a in ('-u', '--user-agent'):
            i += 1
            if i >= len(args):
                _arg_error(prog, f"argument {a}: expected one argument")
            opts.user_agent = args[i]
        elif a.startswith('--user-agent='):
            opts.user_agent = a[13:]
        elif a in ('-v', '--no-video'):
            opts.no_video = True
        elif a == '--':
            i += 1
            if i < len(args):
                opts.target = args[i]
            break
        elif a.startswith('-'):
            _arg_error_unknown(prog, a)
        else:
            if opts.target is None:
                opts.target = a
            else:
                _arg_error(prog, f"unexpected argument '{a}'")
        i += 1

    if opts.target is None:
        print(f'error: the following required arguments were not provided:', file=sys.stderr)
        print(f'  <TARGET>', file=sys.stderr)
        print(file=sys.stderr)
        print(f'Usage: {prog} <TARGET>', file=sys.stderr)
        print(file=sys.stderr)
        print("For more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

    return opts


def _arg_error(prog, msg):
    print(f'error: {msg}', file=sys.stderr)
    print(file=sys.stderr)
    print(f"For more information, try '--help'.", file=sys.stderr)
    sys.exit(2)


def _arg_error_unknown(prog, arg):
    print(f"error: unexpected argument '{arg}' found", file=sys.stderr)
    print(file=sys.stderr)
    print(f"  tip: to pass '{arg}' as a value, use '-- {arg}'", file=sys.stderr)
    print(file=sys.stderr)
    print(f'Usage: {prog} [OPTIONS] <TARGET>', file=sys.stderr)
    print(file=sys.stderr)
    print("For more information, try '--help'.", file=sys.stderr)
    sys.exit(2)


# ===== Main =====

def main():
    opts = parse_args()

    # MHTML implies no-js
    if opts.mhtml:
        opts.no_js = True

    fetcher = Fetcher(opts)
