    def __init__(self):
        self.kind = 'doctype'

class TextNode:
    __slots__ = ['kind', 'data']
    def __init__(self, data):
        self.kind = 'text'
        self.data = data

class CommentNode:
    __slots__ = ['kind', 'data']
    def __init__(self, data):
        self.kind = 'comment'
        self.data = data

class ElementNode:
    __slots__ = ['kind', 'tag', 'attrs', 'children', 'inserted']
    def __init__(self, tag, attrs=None):
        self.kind = 'element'
        self.tag = tag
        self.attrs = attrs if attrs is not None else []  # list of [name, value]
        self.children = []
