# ===== Serializer =====

def _escape_text(text):
    result = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == '&':
            j = i + 1
            if j < n and text[j] == '#':
                k = j + 1
                if k < n and text[k] in ('x', 'X'):
                    k += 1
                    while k < n and text[k] in '0123456789abcdefABCDEF':
                        k += 1
                else:
                    while k < n and text[k].isdigit():
                        k += 1
                if k < n and text[k] == ';':
                    result.append(text[i:k+1])
                    i = k + 1
                    continue
            else:
                k = j
                while k < n and (text[k].isalpha() or text[k].isdigit()):
                    k += 1
                if k < n and text[k] == ';' and k > j:
                    result.append(text[i:k+1])
                    i = k + 1
                    continue
            result.append('&amp;')
        elif c == '<':
            result.append('&lt;')
        elif c == '>':
            result.append('&gt;')
        else:
            result.append(c)
        i += 1
    return ''.join(result)


