def apply_no_js(node):
    if node.kind == 'element':
        node.attrs = [[k, v] for k, v in node.attrs if not k.lower().startswith('on')]
        for p in node.attrs:
            if p[0] in ('href', 'action') and p[1].lower().startswith('javascript:'):
                p[1] = 'javascript:;'
    for c in getattr(node, 'children', []):
        apply_no_js(c)


def unwrap_noscript(node):
    if not hasattr(node, 'children'):
        return
    new = []
    for c in node.children:
        if c.kind == 'element' and c.tag == 'noscript':
            new.append(CommentNode('noscript'))
            new.extend(c.children)
            new.append(CommentNode('/noscript'))
        else:
            unwrap_noscript(c)
            new.append(c)
    node.children = new


def set_robots_meta(head):
    for c in head.children:
        if c.kind == 'element' and c.tag == 'meta':
            if get_attr(c, 'name', '').lower() == 'robots':
                set_attr(c, 'content', 'none')
                return
    m = ElementNode('meta', [['name', 'robots'], ['content', 'none']])
    m.inserted = True
    head.children.append(m)


def build_csp(opts):
    parts = []
    if opts.isolate:
        parts.append("default-src 'unsafe-eval' 'unsafe-inline' data:")
    if opts.no_css:
        parts.append("style-src 'none'")
    if opts.no_fonts:
        parts.append("font-src 'none'")
    if opts.no_frames:
        parts.append("frame-src 'none'")
        parts.append("child-src 'none'")
    if opts.no_js:
        parts.append("script-src 'none'")
    if opts.no_images:
        parts.append("img-src data:")
    return ('; '.join(parts) + ';') if parts else None


def add_csp(head, csp):
    m = ElementNode('meta', [['http-equiv', 'Content-Security-Policy'], ['content', csp]])
    m.inserted = True
    head.children.insert(0, m)


def set_encoding(head, enc):
    for c in head.children:
        if c.kind == 'element' and c.tag == 'meta':
            if has_attr(c, 'charset'):
                set_attr(c, 'charset', enc)
                return
            if get_attr(c, 'http-equiv', '').lower() == 'content-type':
                content = get_attr(c, 'content', '')
                if 'charset=' in content.lower():
                    content = re.sub(r'charset=[^;,\s]+', f'charset={enc}', content, flags=re.I)
                else:
                    content += f';charset={enc}'
                set_attr(c, 'content', content)
                return
    m = ElementNode('meta', [['charset', enc]])
    m.inserted = True
    head.children.append(m)


