                    out.append(_norm_str(c2,False)); i=ei; continue
            out.append(css[i]); i+=1
        return ''.join(out)

    def _infont(self,css,pos):
        b=css[max(0,pos-500):pos].lower()
        lf=b.rfind('@font-face')
        if lf==-1: return False
        s=b[lf:]; return s.count('{')>s.count('}')

    def _imp(self,css,start):
        i=start+7; n=len(css)
        while i<n and css[i] in ' \t\n\r': i+=1
        if i>=n: return None
        if css[i:i+4].lower()=='url(':
            url,ei=self._xurl(css,i+4)
            if url is not None: return f'@import url("{self._emb(url)}")',ei
        elif css[i] in ('"',"'"):
            c2,ei=_css_str(css,i,css[i])
            if c2 is not None:
                return f'@import "{self._emb(_unescape_css_str(c2))}"',ei
        return None

    def _xurl(self,css,start):
        i=start; n=len(css)
        while i<n and css[i] in ' \t\n\r': i+=1
        if i>=n: return None,None
        if css[i] in ('"',"'"):
            q=css[i]; i+=1; e=css.find(q,i)
            if e==-1: return None,None
            url=css[i:e]; i=e+1
        else:
            e=i
            while e<n and css[e] not in (' ','\t','\n','\r',')'): e+=1
            url=css[i:e]; i=e
        while i<n and css[i] in ' \t\n\r': i+=1
        if i<n and css[i]==')': i+=1
        return url,i

    def _emb(self,url,is_font=False):
        if not url or url.startswith('data:') or url.startswith('#'): return url
        if is_font and self.opts.no_fonts: return ''
        au=resolve(self.base,url)
        r=self.fetcher.fetch(au)
        if r is None: return ''
        cont,m=r
        if not m: m=mime(au)
        enc=base64.b64encode(cont).decode('ascii')
        return f'data:{m};base64,{enc}' if m else f'data:;base64,{enc}'


def _unescape_css_str(s):
    """Unescape a CSS string content (remove backslash escapes)."""
    r=[]; i=0; n=len(s)
    while i<n:
        if s[i]=='\\' and i+1<n: r.append(s[i+1]); i+=2
        else: r.append(s[i]); i+=1
    return ''.join(r)


class Fetcher:
    def __init__(self,opts):
        self.opts=opts; self._c={}
        if opts.insecure:
            self._ssl=ssl.create_default_context()
            self._ssl.check_hostname=False; self._ssl.verify_mode=ssl.CERT_NONE
        else: self._ssl=None
    def fetch(self,url):
        if url in self._c: return self._c[url]
        r=self._do(url); self._c[url]=r; return r
    def _do(self,url):
        p=urllib.parse.urlparse(url)
        if p.scheme=='file': return self._file(url,p)
        if p.scheme in ('http','https'): return self._http(url)
        if p.scheme=='data': return self._data(url)
        return None
    def _file(self,url,p):
        path=urllib.request.url2pathname(p.path)
        if not os.path.isfile(path):
            if not self.opts.quiet: print(f'{url} (file not found)',file=sys.stderr)
            return None
        if not self.opts.quiet: print(url,file=sys.stderr)
        try:
            with open(path,'rb') as f: return (f.read(),mime(url))
        except OSError: return None
    def _http(self,url):
        if not self._dok(url): return None
        if not self.opts.quiet: print(url,file=sys.stderr)
        try:
            req=urllib.request.Request(url)
            if self.opts.user_agent: req.add_header('User-Agent',self.opts.user_agent)
            kw={'timeout':self.opts.timeout}
            if self._ssl: kw['context']=self._ssl
            resp=urllib.request.urlopen(req,**kw)
            data=resp.read()
            ct=resp.headers.get('Content-Type','')
            m=ct.split(';')[0].strip() if ct else ''
            return (data,m or mime(url))
        except Exception:
            if not self.opts.quiet: print(f'{url} (error sending request for url ({url}))',file=sys.stderr)
            return None
    def _data(self,url):
        try:
            rest=url[5:]; hdr,_,data=rest.partition(',')
            if ';base64' in hdr:
                return (base64.b64decode(data),hdr.replace(';base64','').strip())
            return (urllib.parse.unquote_to_bytes(data),hdr.strip())
        except: return None
    def _dok(self,url):
        if not self.opts.domain: return True
        host=urllib.parse.urlparse(url).netloc.lower().split(':')[0]
        if self.opts.blacklist_domains:
            for d in self.opts.domain:
                d=d.lower().lstrip('.')
                if host==d or host.endswith('.'+d): return False
            return True
        else:
            for d in self.opts.domain:
                d=d.lower().lstrip('.')
                if host==d or host.endswith('.'+d): return True
            return False


BLANK_PNG=('data:image/png,%89PNG%0D%0A%1A%0A%00%00%00%0DIHDR%00%00%00%0D%00%00%00%0D'
           '%08%04%00%00%00%D8%E2%2C%F7%00%00%00%11IDATx%DAcd%C0%09%18G%A5%28%96%02%00'
           '%0A%F8%00%0E%CB%8A%EB%16%00%00%00%00IEND%AEB%60%82')


def proc_doc(doc,base,opts,fetcher):
    eff=base; bn=None
    def fb(n):
        nonlocal eff,bn
        if n.kind=='element' and n.tag=='base':
            h=gattr(n,'href')
            if h and bn is None:
                bn=n
                if not opts.base_url: eff=h
        for c in getattr(n,'children',[]): fb(c)
    fb(doc)
    if opts.base_url:
        eff=opts.base_url
        hd=find_head(doc)
        if bn is not None: sattr(bn,'href',opts.base_url)
        else:
            nb=EN('base',[['href',opts.base_url]]); nb.ins=True
            hd.children.insert(0,nb)
    _pn(doc,eff,opts,fetcher,None)
    return eff

def _pn(nd,base,opts,fetcher,ptag):
    if nd.kind not in ('element','document'): return
    if nd.kind=='document':
        for c in nd.children: _pn(c,base,opts,fetcher,None)
        return
    tag=nd.tag
    s=gattr(nd,'style')
    if s: sattr(nd,'style',CSS(base,fetcher,opts).proc(s))
    if tag=='link': _lnk(nd,base,opts,fetcher)
    elif tag=='style': _sty(nd,base,opts,fetcher)
    elif tag=='script': _scr(nd,base,opts,fetcher)
    elif tag=='img': _img(nd,base,opts,fetcher)
    elif tag=='source': _src(nd,base,opts,fetcher,ptag)
    elif tag in ('video','audio'): _med(nd,base,opts,fetcher)
    elif tag in ('iframe','frame'): _ifr(nd,base,opts,fetcher)
    elif tag=='input': _inp(nd,base,opts,fetcher)
    elif tag=='a': _anc(nd,base,opts)
    elif tag=='form': _frm(nd,base)
    elif tag=='image': _svi(nd,base,opts,fetcher)
    elif tag=='use': _svu(nd,base,opts,fetcher)
    elif tag=='meta': _met(nd)
    for c in nd.children: _pn(c,base,opts,fetcher,tag)

def _emb(url,base,fetcher):
    if not url or url.startswith('data:'): return url,True
    au=resolve(base,url)
    r=fetcher.fetch(au)
    if r is None: return None,False
    cont,m=r
    if not m: m=mime(au)
    frag=('#'+url.split('#',1)[1]) if '#' in url else ''
    enc=base64.b64encode(cont).decode('ascii')
    return (f'data:{m};base64,{enc}{frag}' if m else f'data:;base64,{enc}{frag}'),True

def _lnk(nd,base,opts,fetcher):
    rel=gattr(nd,'rel','').lower().strip()
    href=gattr(nd,'href','')
    dattr(nd,'integrity')
    if rel=='stylesheet':
        if opts.no_css: dattr(nd,'href'); return
        if href:
            if href.startswith('data:'):
                r=fetcher._data(href)
                if r:
                    css=r[0].decode('utf-8',errors='replace')
                    proc=CSS(base,fetcher,opts).proc(css)
                    enc=base64.b64encode(proc.encode('utf-8')).decode('ascii')
                    sattr(nd,'href',f'data:text/css;base64,{enc}')
            else:
                au=resolve(base,href); r=fetcher.fetch(au)
                if r:
                    css=r[0].decode('utf-8',errors='replace')
                    proc=CSS(au,fetcher,opts).proc(css)
                    enc=base64.b64encode(proc.encode('utf-8')).decode('ascii')
                    sattr(nd,'href',f'data:text/css;base64,{enc}')
                else: dattr(nd,'href')
    elif rel in ('icon','shortcut icon','apple-touch-icon','apple-touch-icon-precomposed'):
        if href and not href.startswith('data:'):
            du,ok=_emb(href,base,fetcher)
            if ok and du: sattr(nd,'href',du)
            else: dattr(nd,'href')
    elif rel=='preload': dattr(nd,'rel')
    elif rel in ('prefetch','canonical','alternate','manifest','next','prev','dns-prefetch','preconnect'):
        if href and not href.startswith('data:') and not href.startswith('#'):
            sattr(nd,'href',resolve(base,href))

def _sty(nd,base,opts,fetcher):
    if opts.no_css: nd.children=[]; return
    css=''.join(c.data for c in nd.children if c.kind=='text')
    if css: nd.children=[TN(CSS(base,fetcher,opts).proc(css))]

def _scr(nd,base,opts,fetcher):
    dattr(nd,'integrity')
    if opts.no_js: nd.children=[]; dattr(nd,'src'); return
    src=gattr(nd,'src','')
    if src:
        if src.startswith('data:'):
            r=fetcher._data(src)
            if r: nd.children=[TN(r[0].decode('utf-8',errors='replace'))]; dattr(nd,'src')
        else:
            au=resolve(base,src); r=fetcher.fetch(au)
            if r: nd.children=[TN(r[0].decode('utf-8',errors='replace'))]; dattr(nd,'src')
            else: dattr(nd,'src')

def _img(nd,base,opts,fetcher):
    src=gattr(nd,'src',''); ss=gattr(nd,'srcset','')
    if opts.no_images:
        sattr(nd,'src',BLANK_PNG)
        if ss: dattr(nd,'srcset')
        return
    if src and not src.startswith('data:'):
        du,ok=_emb(src,base,fetcher)
        if ok and du: sattr(nd,'src',du)
        else: dattr(nd,'src')
    if ss: sattr(nd,'srcset',_srcset(ss,base,fetcher))

def _src(nd,base,opts,fetcher,ptag):
    src=gattr(nd,'src',''); ss=gattr(nd,'srcset','')
    no=((ptag=='video' and opts.no_video) or (ptag=='audio' and opts.no_audio))
    if no:
        if src: dattr(nd,'src')
        if ss: dattr(nd,'srcset')
        return
    if src and not src.startswith('data:'):
        du,ok=_emb(src,base,fetcher)
        if ok and du: sattr(nd,'src',du)
        else: dattr(nd,'src')
    if ss: sattr(nd,'srcset',_srcset(ss,base,fetcher))

def _med(nd,base,opts,fetcher):
    tag=nd.tag; src=gattr(nd,'src','')
    no=(tag=='video' and opts.no_video) or (tag=='audio' and opts.no_audio)
    if no:
        if src: dattr(nd,'src')
        return
    if src and not src.startswith('data:'):
        du,ok=_emb(src,base,fetcher)
        if ok and du: sattr(nd,'src',du)
        else: dattr(nd,'src')

def _ifr(nd,base,opts,fetcher):
    src=gattr(nd,'src','')
    if opts.no_frames: sattr(nd,'src',''); return
    if src and not src.startswith('data:'):
        au=resolve(base,src)
        frag=('#'+src.split('#',1)[1]) if '#' in src else ''
        r=fetcher.fetch(au)
        if r:
            sub=parse(r[0].decode('utf-8',errors='replace'))
            _pn(sub,au,opts,fetcher,None)
            out=serdoc(sub)
            enc=base64.b64encode(out.encode('utf-8')).decode('ascii')
            sattr(nd,'src',f'data:text/html;base64,{enc}{frag}')
        else: dattr(nd,'src')

def _inp(nd,base,opts,fetcher):
    if gattr(nd,'type','').lower()!='image': return
    src=gattr(nd,'src','')
    if opts.no_images: sattr(nd,'src',BLANK_PNG); return
    if src and not src.startswith('data:'):
        du,ok=_emb(src,base,fetcher)
        if ok and du: sattr(nd,'src',du)
        else: dattr(nd,'src')

def _anc(nd,base,opts):
    href=gattr(nd,'href','')
    if href:
        low=href.lower()
        if not any(low.startswith(s) for s in ('#','javascript:','mailto:','tel:','data:')):
            sattr(nd,'href',resolve(base,href))
    if opts.no_js:
        nd.attrs=[[k,v] for k,v in nd.attrs if not k.startswith('on')]
        href=gattr(nd,'href','')
        if href and href.lower().startswith('javascript:'): sattr(nd,'href','javascript:;')

def _frm(nd,base):
    a=gattr(nd,'action','')
    if a and not a.lower().startswith(('javascript:','data:')): sattr(nd,'action',resolve(base,a))

def _svi(nd,base,opts,fetcher):
    if opts.no_images:
        dattr(nd,'href'); dattr(nd,'xlink:href'); return
    for attr in ('href','xlink:href'):
        val=gattr(nd,attr,'')
        if val and not val.startswith('data:'):
            du,ok=_emb(val,base,fetcher)
            if ok and du: sattr(nd,attr,du)
            else: dattr(nd,attr)

def _svu(nd,base,opts,fetcher):
    for attr in ('href','xlink:href'):
        val=gattr(nd,attr,'')
        if val and not val.startswith('#') and not val.startswith('data:'):
            du,ok=_emb(val,base,fetcher)
            if ok and du: sattr(nd,attr,du)
            else: dattr(nd,attr)

def _met(nd):
    if gattr(nd,'http-equiv','').lower()=='refresh': dattr(nd,'http-equiv')

def _srcset(ss,base,fetcher):
    parts=[]
    for item in ss.split(','):
        item=item.strip()
        if not item: continue
        tok=item.split(None,1)
        url=tok[0]; desc=tok[1] if len(tok)>1 else ''
        if url.startswith('data:'): parts.append(f'{url} {desc}'.strip()); continue
        du,ok=_emb(url,base,fetcher)
        parts.append(f'{du} {desc}'.strip() if (ok and du) else desc.strip())
    return ', '.join(parts)

def apply_nojs(nd):
    if nd.kind=='element':
        nd.attrs=[[k,v] for k,v in nd.attrs if not k.lower().startswith('on')]
        for p in nd.attrs:
            if p[0] in ('href','action') and p[1].lower().startswith('javascript:'): p[1]='javascript:;'
    for c in getattr(nd,'children',[]): apply_nojs(c)

def unwrap_ns(nd):
    if not hasattr(nd,'children'): return
    new=[]
    for c in nd.children:
        if c.kind=='element' and c.tag=='noscript':
            new.append(CN('noscript')); new.extend(c.children); new.append(CN('/noscript'))
        else: unwrap_ns(c); new.append(c)
    nd.children=new

def set_robots(head):
    for c in head.children:
        if c.kind=='element' and c.tag=='meta' and gattr(c,'name','').lower()=='robots':
            sattr(c,'content','none'); return
    m=EN('meta',[['name','robots'],['content','none']]); m.ins=True; head.children.append(m)

def build_csp(opts):
    p=[]
    if opts.isolate: p.append("default-src 'unsafe-eval' 'unsafe-inline' data:")
    if opts.no_css: p.append("style-src 'none'")
    if opts.no_fonts: p.append("font-src 'none'")
    if opts.no_frames: p.append("frame-src 'none'"); p.append("child-src 'none'")
    if opts.no_js: p.append("script-src 'none'")
    if opts.no_images: p.append("img-src data:")
    return ('; '.join(p)+';') if p else None

def add_csp(head,csp):
    m=EN('meta',[['http-equiv','Content-Security-Policy'],['content',csp]]); m.ins=True
    head.children.insert(0,m)

def set_enc(head,enc):
    for c in head.children:
        if c.kind=='element' and c.tag=='meta':
            if hattr(c,'charset'): sattr(c,'charset',enc); return
            if gattr(c,'http-equiv','').lower()=='content-type':
                ct=gattr(c,'content','')
                if 'charset=' in ct.lower():
                    ct=re.sub(r'charset=[^;,\s]+',f'charset={enc}',ct,flags=re.I)
                else: ct+=f';charset={enc}'
                sattr(c,'content',ct); return
    m=EN('meta',[['charset',enc]]); m.ins=True; head.children.append(m)

def fetch_target(target,opts):
    if target=='-': return sys.stdin.buffer.read(),opts.base_url or 'http://example.com/'
    p=urllib.parse.urlparse(target)
    if p.scheme in ('http','https'):
        fetcher=Fetcher(opts)
        if not opts.quiet: print(target,file=sys.stderr)
        r=fetcher.fetch(target)
        if r is None: print('Error: could not retrieve target document',file=sys.stderr); sys.exit(1)
        return r[0],target
    elif p.scheme=='file':
        path=urllib.request.url2pathname(p.path)
        if not opts.quiet: print(target,file=sys.stderr)
        if not os.path.isfile(path):
            if not opts.quiet: print(f'{target} (file not found)',file=sys.stderr)
            print('Error: could not retrieve target document',file=sys.stderr); sys.exit(1)
        with open(path,'rb') as f: return f.read(),target
    else:
        ap=os.path.abspath(target)
        if os.path.isfile(ap):
            bu='file://'+ap
            if not opts.quiet: print(bu,file=sys.stderr)
            with open(ap,'rb') as f: return f.read(),bu
        http_url=f'http://{target}'
        if not opts.quiet: print(http_url,file=sys.stderr)
        fetcher=Fetcher(opts)
        r=fetcher.fetch(http_url)
        if r is None: print('Error: could not retrieve target document',file=sys.stderr); sys.exit(1)
        return r[0],http_url

def to_mhtml(html,base):
    B='----=_NextPart_000_0000'; CR='\r\n'
    return (f'MIME-Version: 1.0{CR}'
            f'Content-Type: multipart/related; boundary="{B}"{CR}'
            f'{CR}'
            f'------=_NextPart_000_0000{CR}'
            f'Content-Type: text/html; charset="utf-8"{CR}'
            f'Content-Location: http://example.com/{CR}'
            f'{CR}'
            f'{html}'
            f'------=_NextPart_000_0000--{CR}')

