    if src and not src.startswith('data:'):
        du,ok=_emb(src,base,fetcher)
        if ok and du: sattr(nd,'src',du)
        else: dattr(nd,'src')

def _ifr(nd,base,opts,fetcher):
    src=gattr(nd,'src','')
    if opts.no_frames: sattr(nd,'src',''); return
    if src and not src.startswith('data:'):
        au=resolve(base,src)
        frag=('#'+src.split('#',1)[1]) if '#' in src else ''
        r=fetcher.fetch(au)
        if r:
            sub=parse(r[0].decode('utf-8',errors='replace'))
            _pn(sub,au,opts,fetcher,None)
            out=serdoc(sub)
            enc=base64.b64encode(out.encode('utf-8')).decode('ascii')
            sattr(nd,'src',f'data:text/html;base64,{enc}{frag}')
        else: dattr(nd,'src')

def _inp(nd,base,opts,fetcher):
    if gattr(nd,'type','').lower()!='image': return
    src=gattr(nd,'src','')
    if opts.no_images: sattr(nd,'src',BLANK_PNG); return
    if src and not src.startswith('data:'):
        du,ok=_emb(src,base,fetcher)
        if ok and du: sattr(nd,'src',du)
        else: dattr(nd,'src')

def _anc(nd,base,opts):
    href=gattr(nd,'href','')
    if href:
        low=href.lower()
        if not any(low.startswith(s) for s in ('#','javascript:','mailto:','tel:','data:')):
            sattr(nd,'href',resolve(base,href))
    if opts.no_js:
        nd.attrs=[[k,v] for k,v in nd.attrs if not k.startswith('on')]
        href=gattr(nd,'href','')
        if href and href.lower().startswith('javascript:'): sattr(nd,'href','javascript:;')

def _frm(nd,base):
    a=gattr(nd,'action','')
    if a and not a.lower().startswith(('javascript:','data:')): sattr(nd,'action',resolve(base,a))

def _svi(nd,base,opts,fetcher):
    if opts.no_images:
        dattr(nd,'href'); dattr(nd,'xlink:href'); return
    for attr in ('href','xlink:href'):
        val=gattr(nd,attr,'')
        if val and not val.startswith('data:'):
            du,ok=_emb(val,base,fetcher)
            if ok and du: sattr(nd,attr,du)
            else: dattr(nd,attr)

def _svu(nd,base,opts,fetcher):
    for attr in ('href','xlink:href'):
        val=gattr(nd,attr,'')
        if val and not val.startswith('#') and not val.startswith('data:'):
            du,ok=_emb(val,base,fetcher)
            if ok and du: sattr(nd,attr,du)
            else: dattr(nd,attr)

def _met(nd):
    if gattr(nd,'http-equiv','').lower()=='refresh': dattr(nd,'http-equiv')

def _srcset(ss,base,fetcher):
    parts=[]
    for item in ss.split(','):
        item=item.strip()
        if not item: continue
        tok=item.split(None,1)
        url=tok[0]; desc=tok[1] if len(tok)>1 else ''
        if url.startswith('data:'): parts.append(f'{url} {desc}'.strip()); continue
        du,ok=_emb(url,base,fetcher)
        parts.append(f'{du} {desc}'.strip() if (ok and du) else desc.strip())
    return ', '.join(parts)

def apply_nojs(nd):
    if nd.kind=='element':
        nd.attrs=[[k,v] for k,v in nd.attrs if not k.lower().startswith('on')]
        for p in nd.attrs:
            if p[0] in ('href','action') and p[1].lower().startswith('javascript:'): p[1]='javascript:;'
    for c in getattr(nd,'children',[]): apply_nojs(c)

def unwrap_ns(nd):
    if not hasattr(nd,'children'): return
    new=[]
    for c in nd.children:
        if c.kind=='element' and c.tag=='noscript':
            new.append(CN('noscript')); new.extend(c.children); new.append(CN('/noscript'))
        else: unwrap_ns(c); new.append(c)
    nd.children=new

def set_robots(head):
    for c in head.children:
        if c.kind=='element' and c.tag=='meta' and gattr(c,'name','').lower()=='robots':
            sattr(c,'content','none'); return
    m=EN('meta',[['name','robots'],['content','none']]); m.ins=True; head.children.append(m)

def build_csp(opts):
    p=[]
    if opts.isolate: p.append("default-src 'unsafe-eval' 'unsafe-inline' data:")
    if opts.no_css: p.append("style-src 'none'")
    if opts.no_fonts: p.append("font-src 'none'")
    if opts.no_frames: p.append("frame-src 'none'"); p.append("child-src 'none'")
    if opts.no_js: p.append("script-src 'none'")
    if opts.no_images: p.append("img-src data:")
    return ('; '.join(p)+';') if p else None

def add_csp(head,csp):
    m=EN('meta',[['http-equiv','Content-Security-Policy'],['content',csp]]); m.ins=True
    head.children.insert(0,m)

def set_enc(head,enc):
    for c in head.children:
        if c.kind=='element' and c.tag=='meta':
            if hattr(c,'charset'): sattr(c,'charset',enc); return
            if gattr(c,'http-equiv','').lower()=='content-type':
                ct=gattr(c,'content','')
                if 'charset=' in ct.lower():
                    ct=re.sub(r'charset=[^;,\s]+',f'charset={enc}',ct,flags=re.I)
                else: ct+=f';charset={enc}'
                sattr(c,'content',ct); return
    m=EN('meta',[['charset',enc]]); m.ins=True; head.children.append(m)

def fetch_target(target,opts):
    if target=='-': return sys.stdin.buffer.read(),opts.base_url or 'http://example.com/'
    p=urllib.parse.urlparse(target)
    if p.scheme in ('http','https'):
        fetcher=Fetcher(opts)
        if not opts.quiet: print(target,file=sys.stderr)
        r=fetcher.fetch(target)
        if r is None: print('Error: could not retrieve target document',file=sys.stderr); sys.exit(1)
        return r[0],target
    elif p.scheme=='file':
        path=urllib.request.url2pathname(p.path)
        if not opts.quiet: print(target,file=sys.stderr)
        if not os.path.isfile(path):
            if not opts.quiet: print(f'{target} (file not found)',file=sys.stderr)
            print('Error: could not retrieve target document',file=sys.stderr); sys.exit(1)
        with open(path,'rb') as f: return f.read(),target
    else:
        ap=os.path.abspath(target)
        if os.path.isfile(ap):
            bu='file://'+ap
            if not opts.quiet: print(bu,file=sys.stderr)
            with open(ap,'rb') as f: return f.read(),bu
        http_url=f'http://{target}'
        if not opts.quiet: print(http_url,file=sys.stderr)
        fetcher=Fetcher(opts)
        r=fetcher.fetch(http_url)
        if r is None: print('Error: could not retrieve target document',file=sys.stderr); sys.exit(1)
        return r[0],http_url

def to_mhtml(html,base):
    B='----=_NextPart_000_0000'; CR='\r\n'
    return (f'MIME-Version: 1.0{CR}'
            f'Content-Type: multipart/related; boundary="{B}"{CR}'
            f'{CR}'
            f'------=_NextPart_000_0000{CR}'
            f'Content-Type: text/html; charset="utf-8"{CR}'
            f'Content-Location: http://example.com/{CR}'
            f'{CR}'
            f'{html}'
            f'------=_NextPart_000_0000--{CR}')

BANNER=""" _____    _____________   __________     ___________________    ___
|     \\  /             \\ |          |   |                   |  |   |
|      \\/       __      \\|    __    |   |    ___     ___    |__|   |
|              |  |          |  |   |   |   |   |   |   |          |
|   |\\    /|   |__|          |__|   |___|   |   |   |   |    __    |
|   | \\__/ |          |\\                    |   |   |   |   |  |   |
|___|      |__________| \\___________________|   |___|   |___|  |___|"""

def print_help(prog):
    print(BANNER); print()
    print(f'monolith {VERSION}'); print()
    print('CLI tool and library for saving web pages as a single HTML file'); print()
    print(f'Usage: {prog} [OPTIONS] <TARGET>'); print()
    print('Arguments:')
    print('  <TARGET>  URL or file path, use - for STDIN'); print()
    print('Options:')
    for s in [
        '  -a, --no-audio                      Remove audio sources',
        '  -b, --base-url <http://localhost/>  Set custom base URL',
        '  -B, --blacklist-domains             Treat specified domains as blacklist',
        '  -c, --no-css                        Remove CSS',
        '  -C, --cookie-file <cookies.txt>     Specify cookie file',
        '  -d, --domain <example.com>          Specify domains to use for white/black-listing',
        '  -e, --ignore-errors                 Ignore network errors',
        '  -E, --encoding <UTF-8>              Enforce custom charset',
        '  -f, --no-frames                     Remove frames and iframes',
        '  -F, --no-fonts                      Remove fonts',
        '  -i, --no-images                     Remove images',
        '  -I, --isolate                       Cut off document from the Internet',
        '  -j, --no-js                         Remove JavaScript',
        '  -k, --insecure                      Allow invalid X.509 (TLS) certificates',
        '  -m, --mhtml                         Use MHTML as output format',
        '  -M, --no-metadata                   Exclude timestamp and source information',
        '  -n, --unwrap-noscript               Replace NOSCRIPT elements with their contents',
        '  -o, --output <result.html>          File to write to, use - for STDOUT',
        '  -q, --quiet                         Suppress verbosity',
        '  -t, --timeout <60>                  Adjust network request timeout',
        '  -u, --user-agent <Firefox>          Set custom User-Agent string',
        '  -v, --no-video                      Remove video sources',
        '  -h, --help                          Print help',
        '  -V, --version                       Print version',
    ]: print(s)

def parse_args():
    prog=os.path.basename(sys.argv[0]); args=sys.argv[1:]
    class O: pass
    o=O()
    o.target=None; o.no_audio=False; o.base_url=None; o.blacklist_domains=False
    o.no_css=False; o.cookie_file=None; o.domain=[]; o.ignore_errors=False
    o.encoding=None; o.no_frames=False; o.no_fonts=False; o.no_images=False
    o.isolate=False; o.no_js=False; o.insecure=False; o.mhtml=False
    o.no_metadata=False; o.unwrap_noscript=False; o.output=None; o.quiet=False
    o.timeout=60; o.user_agent=None; o.no_video=False
    i=0
    def need_val(a):
        nonlocal i; i+=1
        if i>=len(args):
            print(f'error: argument {a}: expected one argument',file=sys.stderr); sys.exit(2)
        return args[i]
    while i<len(args):
        a=args[i]
        if a in ('-h','--help'): print_help(prog); sys.exit(0)
        elif a in ('-V','--version'): print(f'monolith {VERSION}'); sys.exit(0)
        elif a in ('-a','--no-audio'): o.no_audio=True
        elif a in ('-b','--base-url'): o.base_url=need_val(a)
        elif a.startswith('--base-url='): o.base_url=a[11:]
        elif a in ('-B','--blacklist-domains'): o.blacklist_domains=True
        elif a in ('-c','--no-css'): o.no_css=True
        elif a in ('-C','--cookie-file'): o.cookie_file=need_val(a)
        elif a in ('-d','--domain'): o.domain.append(need_val(a))
        elif a.startswith('--domain='): o.domain.append(a[9:])
        elif a in ('-e','--ignore-errors'): o.ignore_errors=True
        elif a in ('-E','--encoding'): o.encoding=need_val(a)
        elif a.startswith('--encoding='): o.encoding=a[11:]
        elif a in ('-f','--no-frames'): o.no_frames=True
        elif a in ('-F','--no-fonts'): o.no_fonts=True
        elif a in ('-i','--no-images'): o.no_images=True
        elif a in ('-I','--isolate'): o.isolate=True
        elif a in ('-j','--no-js'): o.no_js=True
        elif a in ('-k','--insecure'): o.insecure=True
        elif a in ('-m','--mhtml'): o.mhtml=True
        elif a in ('-M','--no-metadata'): o.no_metadata=True
        elif a in ('-n','--unwrap-noscript'): o.unwrap_noscript=True
        elif a in ('-o','--output'): o.output=need_val(a)
        elif a.startswith('--output='): o.output=a[9:]
        elif a in ('-q','--quiet'): o.quiet=True
        elif a in ('-t','--timeout'):
            v=need_val(a)
            try: o.timeout=int(v)
            except: print(f"error: invalid timeout '{v}'",file=sys.stderr); sys.exit(2)
        elif a.startswith('--timeout='): 
            try: o.timeout=int(a[10:])
            except: sys.exit(2)
        elif a in ('-u','--user-agent'): o.user_agent=need_val(a)
        elif a.startswith('--user-agent='): o.user_agent=a[13:]
        elif a in ('-v','--no-video'): o.no_video=True
        elif a=='--':
            i+=1
            if i<len(args): o.target=args[i]
            break
        elif a.startswith('-'):
            print(f"error: unexpected argument '{a}' found",file=sys.stderr); print(file=sys.stderr)
            print(f"  tip: to pass '{a}' as a value, use '-- {a}'",file=sys.stderr); print(file=sys.stderr)
            print(f'Usage: {prog} [OPTIONS] <TARGET>',file=sys.stderr); print(file=sys.stderr)
            print("For more information, try '--help'.",file=sys.stderr); sys.exit(2)
        else:
            if o.target is None: o.target=a
            else: print(f"error: unexpected argument '{a}'",file=sys.stderr); sys.exit(2)
        i+=1
    if o.target is None:
        print('error: the following required arguments were not provided:',file=sys.stderr)
        print('  <TARGET>',file=sys.stderr); print(file=sys.stderr)
        print(f'Usage: {prog} <TARGET>',file=sys.stderr); print(file=sys.stderr)
        print("For more information, try '--help'.",file=sys.stderr); sys.exit(2)
    return o

def main():
    opts=parse_args()
    if opts.mhtml: opts.no_js=True
    fetcher=Fetcher(opts)
    content,base=fetch_target(opts.target,opts)
    doc=parse(content.decode('utf-8',errors='replace'))
    eff=proc_doc(doc,base,opts,fetcher)
    if opts.no_js: apply_nojs(doc)
    if opts.unwrap_noscript: unwrap_ns(doc)
    head=find_head(doc)
    set_robots(head)
    csp=build_csp(opts)
    if csp: add_csp(head,csp)
    if opts.encoding: set_enc(head,opts.encoding)
    out=serdoc(doc)
    if not opts.no_metadata:
        ts=datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
        src='local source' if base.startswith('file://') else base
        out=f'<!-- Saved from {src} at {ts} using monolith v{VERSION} -->\n'+out
    if opts.mhtml: out=to_mhtml(out,eff)
    ob=out.encode('utf-8')
    if opts.output and opts.output!='-':
        with open(opts.output,'wb') as f: f.write(ob)
    else:
        sys.stdout.buffer.write(ob); sys.stdout.buffer.flush()

if __name__=='__main__': main()
